// W3C traceparent carries random ids and a sampled flag, never user content.

/** Fraction of sends that propagate a sampled traceparent. */
export const SEND_TRACE_SAMPLE_RATIO = 1;

export interface MintedTraceparent {
	// The full W3C `traceparent` header value: `00-<32hex traceId>-<16hex spanId>-<2hex flags>`.
	readonly traceparent: string;
	// The trace id on its own, for stamping onto the desktop log-measure so it
	// correlates with the APM waterfall.
	readonly traceId: string;
	readonly spanId: string;
}

export interface ParsedTraceparent {
	readonly traceId: string;
	readonly spanId: string;
	readonly traceFlags: number;
}

const HEX_TRACE_ID = /^[0-9a-f]{32}$/;
const HEX_SPAN_ID = /^[0-9a-f]{16}$/;
const HEX_FLAGS = /^[0-9a-f]{2}$/;
const ZERO_TRACE_ID = "0".repeat(32);
const ZERO_SPAN_ID = "0".repeat(16);

function randomHex(byteLength: number): string {
	const bytes = new Uint8Array(byteLength);
	globalThis.crypto.getRandomValues(bytes);
	let out = "";
	for (const byte of bytes) {
		out += byte.toString(16).padStart(2, "0");
	}
	return out;
}

export function shouldSampleSend(ratio: number = SEND_TRACE_SAMPLE_RATIO): boolean {
	if (!(ratio > 0)) return false;
	if (ratio >= 1) return true;
	return Math.random() < ratio;
}

/** Mints a W3C traceparent, or returns undefined when crypto is unavailable. */
export function mintTraceparent(sampled: boolean = true): MintedTraceparent | undefined {
	try {
		const traceId = randomHex(16);
		const spanId = randomHex(8);
		const flags = sampled ? "01" : "00";
		return { traceparent: `00-${traceId}-${spanId}-${flags}`, traceId, spanId };
	} catch {
		return undefined;
	}
}

export interface DerivedChildTraceparent {
	readonly traceparent: string;
	readonly spanId: string;
}

/** Derives a child traceparent with the same trace id and flags. */
export function deriveChildTraceparent(
	parent: string | undefined,
): DerivedChildTraceparent | undefined {
	const parsed = parseTraceparent(parent);
	if (parsed === undefined) return undefined;
	try {
		const spanId = randomHex(8);
		const flags = (parsed.traceFlags & 1) === 1 ? "01" : "00";
		return { traceparent: `00-${parsed.traceId}-${spanId}-${flags}`, spanId };
	} catch {
		return undefined;
	}
}

/** Parses a W3C version-00 traceparent. Malformed or newer values return undefined. */
export function parseTraceparent(
	traceparent: string | undefined | null,
): ParsedTraceparent | undefined {
	if (typeof traceparent !== "string") return undefined;
	const parts = traceparent.trim().split("-");
	if (parts.length !== 4) return undefined;
	const [version = "", traceId = "", spanId = "", flags = ""] = parts;
	if (version !== "00") return undefined;
	if (!HEX_TRACE_ID.test(traceId) || traceId === ZERO_TRACE_ID) return undefined;
	if (!HEX_SPAN_ID.test(spanId) || spanId === ZERO_SPAN_ID) return undefined;
	if (!HEX_FLAGS.test(flags)) return undefined;
	const traceFlags = Number.parseInt(flags, 16);
	if (Number.isNaN(traceFlags)) return undefined;
	return { traceId, spanId, traceFlags };
}
