import { promises as fs } from "node:fs";
import { dirname, join } from "node:path";

import type { SandGatewayConnectionInfo } from "../../shared/gateway-connection.js";
import {
	LOCAL_EXEC_DAEMON_CONNECTION_FILENAME,
	LOCAL_EXEC_DAEMON_CREDENTIAL_FILENAME,
	LOCAL_EXEC_DAEMON_DISCOVERY_FILENAME,
	LOCAL_EXEC_DAEMON_LOG_FILENAME,
	LOCAL_EXEC_SUPERVISOR_HEARTBEAT_FILENAME,
	type LocalExecDaemonCredential,
	type LocalExecDaemonDiscovery,
	type LocalExecSupervisorHeartbeat,
} from "../../shared/local-exec-daemon.js";

export interface LocalExecDaemonPaths {
	readonly connectionPath: string;
	readonly discoveryPath: string;
	readonly credentialPath: string;
	readonly logPath: string;
	readonly supervisorHeartbeatPath: string;
}

export function resolveLocalExecDaemonPaths(dataDir: string): LocalExecDaemonPaths {
	return {
		connectionPath: join(dataDir, LOCAL_EXEC_DAEMON_CONNECTION_FILENAME),
		discoveryPath: join(dataDir, LOCAL_EXEC_DAEMON_DISCOVERY_FILENAME),
		credentialPath: join(dataDir, LOCAL_EXEC_DAEMON_CREDENTIAL_FILENAME),
		logPath: join(dataDir, LOCAL_EXEC_DAEMON_LOG_FILENAME),
		supervisorHeartbeatPath: join(dataDir, LOCAL_EXEC_SUPERVISOR_HEARTBEAT_FILENAME),
	};
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function isInteger(value: unknown): value is number {
	return typeof value === "number" && Number.isInteger(value);
}

function parseDiscovery(value: unknown): LocalExecDaemonDiscovery | null {
	if (!isRecord(value)) return null;
	const { pid, startedAt, inflightCount } = value;
	if (!isInteger(pid) || pid <= 0) return null;
	if (typeof startedAt !== "number" || Number.isNaN(startedAt)) return null;
	if (inflightCount === undefined) return { pid, startedAt };
	if (!isInteger(inflightCount) || inflightCount < 0) return null;
	return { pid, startedAt, inflightCount };
}

function isFileMissing(error: unknown): boolean {
	return isRecord(error) && error.code === "ENOENT";
}

export async function readLocalExecDaemonDiscovery(
	path: string,
): Promise<LocalExecDaemonDiscovery | null> {
	let raw: string;
	try {
		raw = await fs.readFile(path, "utf8");
	} catch (error) {
		if (isFileMissing(error)) return null;
		throw error;
	}
	let parsed: unknown;
	try {
		parsed = JSON.parse(raw);
	} catch {
		return null;
	}
	return parseDiscovery(parsed);
}

async function writeSecretJsonFile(path: string, data: unknown): Promise<void> {
	await fs.mkdir(dirname(path), { recursive: true });
	const tempPath = `${path}.${process.pid}.tmp`;
	await fs.writeFile(tempPath, JSON.stringify(data), { encoding: "utf8", mode: 0o600 });
	await fs.rename(tempPath, path);
}

export function writeLocalExecDaemonConnection(
	connection: SandGatewayConnectionInfo,
	path: string,
): Promise<void> {
	return writeSecretJsonFile(path, connection);
}

export function writeLocalExecDaemonCredential(
	credential: LocalExecDaemonCredential,
	path: string,
): Promise<void> {
	return writeSecretJsonFile(path, credential);
}

export function writeLocalExecSupervisorHeartbeat(path: string): Promise<void> {
	const heartbeat: LocalExecSupervisorHeartbeat = { pid: process.pid, at: Date.now() };
	return writeSecretJsonFile(path, heartbeat);
}

export async function removeLocalExecDaemonFile(path: string): Promise<void> {
	try {
		await fs.unlink(path);
	} catch (error) {
		if (!isFileMissing(error)) throw error;
	}
}
