import type { RpcClientOf } from "@sand/dune/rpc";
import type { Clock } from "@sand/dune/scheduling";

import type {
	SandGatewayDnsDiagnosticReport,
	SandGatewayReachabilityReport,
} from "../../shared/gateway-reachability.js";
import type {
	CoordinatorControlRpcContract,
	CoordinatorGatewayCommandSpanReport,
	CoordinatorTransportStageReport,
} from "../../shared/rpc/coordinator-control.js";

export type TransportTelemetryEgress = Pick<
	RpcClientOf<CoordinatorControlRpcContract>,
	| "reportTransportStage"
	| "reportGatewayReachability"
	| "reportGatewayDnsDiagnostic"
	| "reportGatewayCommandSpan"
>;

export type SendTransportTimedStage = "gateway-connect" | "gateway-post";

export type SendTransportMarkStage = "gateway-acceptance" | "gateway-retry";

/** Frozen APM stage name for an authoritative SSE echo. */
export const SSE_ECHO_STAGE = "echo-coordinator-sse";

export interface CoordinatorSendKey {
	readonly accountSlot: string;
	readonly clientNonce: string;
}

export interface CoordinatorSendIdentity {
	readonly accountSlot: string;
	readonly clientNonce: string | null;
	readonly traceparent: string | null;
}

export interface SendStageTiming {
	complete(): void;
	fail(): void;
}

export interface SendTrace {
	beginStage(stage: SendTransportTimedStage, attempt: number): SendStageTiming;
	markStage(stage: SendTransportMarkStage, attempt: number): void;
}

/** Records bounded, fire-and-forget transport reports keyed by send identity. */
export interface TransportStageRecorder {
	beginSend(identity: CoordinatorSendIdentity): SendTrace;
	recordSendEcho(key: CoordinatorSendKey): void;
	recordTransportStage(report: CoordinatorTransportStageReport): void;
	recordGatewayCommandSpan(report: CoordinatorGatewayCommandSpanReport): void;
	recordGatewayReachability(report: SandGatewayReachabilityReport): void;
	recordGatewayDnsDiagnostic(report: SandGatewayDnsDiagnosticReport): void;
}

export interface TransportStageRecorderOptions {
	readonly clock: Clock;
	readonly egress: TransportTelemetryEgress;
}

export const MAX_IN_FLIGHT_TRANSPORT_REPORTS = 64;

export const PENDING_SEND_ECHO_MAX = 64;
export const PENDING_SEND_ECHO_TTL_MS = 120_000;

const INERT_STAGE: SendStageTiming = {
	complete() {},
	fail() {},
};

const INERT_TRACE: SendTrace = {
	beginStage: () => INERT_STAGE,
	markStage() {},
};

interface PendingSendEcho {
	readonly traceparent: string;
	readonly armedAtMonotonicMs: number;
}

function sendKeyOf(key: CoordinatorSendKey): string {
	return `${key.accountSlot}\u0000${key.clientNonce}`;
}

export function createTransportStageRecorder(
	options: TransportStageRecorderOptions,
): TransportStageRecorder {
	const { clock, egress } = options;

	let inFlightReports = 0;
	const forward = (dispatch: () => Promise<void>): void => {
		if (inFlightReports >= MAX_IN_FLIGHT_TRANSPORT_REPORTS) return;
		inFlightReports += 1;
		const settle = (): void => {
			inFlightReports -= 1;
		};
		try {
			void dispatch().then(settle, settle);
		} catch {
			settle();
		}
	};
	const forwardStage = (report: CoordinatorTransportStageReport): void => {
		forward(() => egress.reportTransportStage(report));
	};

	const pendingEchoes = new Map<string, PendingSendEcho>();
	const armEcho = (key: CoordinatorSendKey, traceparent: string): void => {
		const nowMonotonicMs = clock.monotonicNow();
		for (const [armedKey, pending] of pendingEchoes) {
			if (nowMonotonicMs - pending.armedAtMonotonicMs > PENDING_SEND_ECHO_TTL_MS) {
				pendingEchoes.delete(armedKey);
			}
		}
		if (pendingEchoes.size >= PENDING_SEND_ECHO_MAX) {
			const oldest = pendingEchoes.keys().next().value;
			if (oldest !== undefined) pendingEchoes.delete(oldest);
		}
		pendingEchoes.set(sendKeyOf(key), { traceparent, armedAtMonotonicMs: nowMonotonicMs });
	};

	return {
		beginSend(identity) {
			const { accountSlot, clientNonce, traceparent } = identity;
			if (clientNonce == null || clientNonce === "") return INERT_TRACE;
			const sampledTraceparent = traceparent == null || traceparent === "" ? null : traceparent;
			if (sampledTraceparent != null) {
				armEcho({ accountSlot, clientNonce }, sampledTraceparent);
			}
			return {
				beginStage(stage, attempt) {
					const startEpochMs = clock.now();
					const startMonotonicMs = clock.monotonicNow();
					let settled = false;
					const settle = (isError: boolean): void => {
						if (settled) return;
						settled = true;
						forwardStage({
							accountSlot,
							clientNonce,
							stage,
							attempt,
							traceparent: sampledTraceparent,
							startEpochMs,
							durationMs: clock.monotonicNow() - startMonotonicMs,
							isError,
						});
					};
					return {
						complete: () => settle(false),
						fail: () => settle(true),
					};
				},
				markStage(stage, attempt) {
					forwardStage({
						accountSlot,
						clientNonce,
						stage,
						attempt,
						traceparent: sampledTraceparent,
						startEpochMs: clock.now(),
						durationMs: 0,
						isError: false,
					});
				},
			};
		},
		recordSendEcho(key) {
			const armedKey = sendKeyOf(key);
			const pending = pendingEchoes.get(armedKey);
			if (pending == null) return;
			pendingEchoes.delete(armedKey);
			forwardStage({
				accountSlot: key.accountSlot,
				clientNonce: key.clientNonce,
				stage: SSE_ECHO_STAGE,
				attempt: 0,
				traceparent: pending.traceparent,
				startEpochMs: clock.now(),
				durationMs: 0,
				isError: false,
			});
		},
		recordTransportStage(report) {
			forwardStage(report);
		},
		recordGatewayCommandSpan(report) {
			forward(() => egress.reportGatewayCommandSpan(report));
		},
		recordGatewayReachability(report) {
			forward(() => egress.reportGatewayReachability(report));
		},
		recordGatewayDnsDiagnostic(report) {
			forward(() => egress.reportGatewayDnsDiagnostic(report));
		},
	};
}
