import {
	type Clock,
	createDeadlinePolicy,
	type DeadlinePolicy,
	realClock,
} from "@sand/dune/scheduling";

import type { SandGatewayConnectionInfo } from "../../shared/gateway-connection.js";
import { GATEWAY_HEALTH_PATH, type SandGatewayHealth } from "../../shared/gateway-wire.js";
import {
	classifyBaseUrlKind,
	classifyGatewayFetchFailure,
	outcomeForHttpStatus,
	type SandGatewayReachabilitySink,
} from "./gateway-reachability.js";

export const HEALTH_TIMEOUT_MS = 1_500;

export const HEALTH_PROBE_TTL_MS = 5_000;

const DISABLE_HEALTH_TTL_ENV = "SAND_DISABLE_GATEWAY_HEALTH_TTL";

const DISABLE_STREAM_LIVENESS_ENV = "SAND_DISABLE_GATEWAY_STREAM_LIVENESS";

export interface CoordinatorHostSupervisorTiming {
	readonly clock: Clock;
	readonly healthProbeDeadline: DeadlinePolicy;
}

export function createCoordinatorHostSupervisorTiming(): CoordinatorHostSupervisorTiming {
	return {
		clock: realClock,
		healthProbeDeadline: createDeadlinePolicy({
			name: "gateway-health-probe",
			timeoutMs: HEALTH_TIMEOUT_MS,
		}),
	};
}

export interface CoordinatorHostSupervisorOptions {
	readonly resolveGatewayConnection: () => Promise<SandGatewayConnectionInfo>;
	readonly timing: CoordinatorHostSupervisorTiming;
	readonly isTransportLive?: () => boolean;
	readonly onReachability?: SandGatewayReachabilitySink;
}

export class GatewayConnectResolveAbandonedError extends Error {
	constructor() {
		super("the gateway connection resolve was abandoned before it answered");
		this.name = "GatewayConnectResolveAbandonedError";
	}
}

type ConnectionAttempt = {
	readonly healthEpoch: number;
	readonly promise: Promise<SandGatewayConnectionInfo>;
	state: "pending" | "settled";
	isRetired: boolean;
	hasWaiter: boolean;
	readonly retirement: Promise<never>;
	retire(): void;
};

async function fetchHealth(
	timing: CoordinatorHostSupervisorTiming,
	baseUrl: string,
	headers?: Readonly<Record<string, string>>,
	onReachability?: SandGatewayReachabilitySink,
): Promise<SandGatewayHealth | null> {
	const startMonotonicMs = timing.clock.monotonicNow();
	const report = (r: Parameters<SandGatewayReachabilitySink>[0]): void => {
		try {
			onReachability?.(r, baseUrl);
		} catch {}
	};
	try {
		// Anyrun's pod proxy requires its network-token header on the unauthenticated /health route.
		const response = await timing.healthProbeDeadline.run((signal) =>
			fetch(`${baseUrl}${GATEWAY_HEALTH_PATH}`, {
				signal,
				...(headers != null ? { headers: { ...headers } } : {}),
			}),
		);
		if (!response.ok) {
			report({
				outcome: outcomeForHttpStatus(response.status) ?? "network",
				method: "health",
				latencyMs: timing.clock.monotonicNow() - startMonotonicMs,
				baseUrlKind: classifyBaseUrlKind(baseUrl),
				httpStatus: response.status,
			});
			return null;
		}
		const health = (await response.json()) as SandGatewayHealth;
		return health.ok === true ? health : null;
	} catch (error) {
		const { outcome, causeSummary } = classifyGatewayFetchFailure(error);
		report({
			outcome,
			method: "health",
			latencyMs: timing.clock.monotonicNow() - startMonotonicMs,
			baseUrlKind: classifyBaseUrlKind(baseUrl),
			causeSummary,
		});
		return null;
	}
}

export class SandHostSupervisor {
	private connection: SandGatewayConnectionInfo | undefined;
	private lastHealthyAtMs = Number.NEGATIVE_INFINITY;
	private healthEpoch = 0;
	private latestConnectionAttempt: ConnectionAttempt | undefined;
	private readonly healthTtlDisabled: boolean;
	private readonly streamLivenessDisabled: boolean;

	constructor(private readonly options: CoordinatorHostSupervisorOptions) {
		this.healthTtlDisabled = process.env[DISABLE_HEALTH_TTL_ENV] === "1";
		this.streamLivenessDisabled = process.env[DISABLE_STREAM_LIVENESS_ENV] === "1";
	}

	private getOrStartConnectionAttempt(healthEpoch: number): ConnectionAttempt {
		const currentAttempt = this.latestConnectionAttempt;
		if (
			currentAttempt != null &&
			currentAttempt.healthEpoch === healthEpoch &&
			currentAttempt.state === "pending" &&
			!currentAttempt.isRetired
		) {
			return currentAttempt;
		}

		let release = (): void => {};
		const retirement = new Promise<never>((_resolve, reject) => {
			release = () => reject(new GatewayConnectResolveAbandonedError());
		});
		void retirement.catch(() => {});
		const attempt: ConnectionAttempt = {
			healthEpoch,
			promise: this.options.resolveGatewayConnection(),
			state: "pending",
			isRetired: false,
			hasWaiter: false,
			retirement,
			retire: () => {
				if (attempt.isRetired) return;
				attempt.isRetired = true;
				release();
			},
		};
		this.latestConnectionAttempt = attempt;
		const markSettled = (): void => {
			attempt.state = "settled";
		};
		void attempt.promise.then(markSettled, markSettled);
		return attempt;
	}

	private getLatestAttemptForCurrentEpoch(): ConnectionAttempt {
		const currentAttempt = this.latestConnectionAttempt;
		if (
			currentAttempt != null &&
			currentAttempt.healthEpoch === this.healthEpoch &&
			!currentAttempt.isRetired
		) {
			return currentAttempt;
		}
		return this.getOrStartConnectionAttempt(this.healthEpoch);
	}

	private async awaitAttempt(
		attempt: ConnectionAttempt,
		signal: AbortSignal | undefined,
	): Promise<SandGatewayConnectionInfo> {
		if (signal == null) {
			attempt.hasWaiter = true;
			return await Promise.race([attempt.promise, attempt.retirement]);
		}
		// AbortSignal does not replay the abort event for an already-aborted signal.
		if (signal.aborted) {
			if (!attempt.hasWaiter) attempt.retire();
			throw new GatewayConnectResolveAbandonedError();
		}
		attempt.hasWaiter = true;
		const onAbort = (): void => attempt.retire();
		signal.addEventListener("abort", onAbort, { once: true });
		try {
			return await Promise.race([attempt.promise, attempt.retirement]);
		} finally {
			signal.removeEventListener("abort", onAbort);
		}
	}

	invalidateHealthCache(): void {
		this.healthEpoch += 1;
		this.lastHealthyAtMs = Number.NEGATIVE_INFINITY;
		this.latestConnectionAttempt?.retire();
	}

	async ensureConnection(signal?: AbortSignal): Promise<SandGatewayConnectionInfo> {
		const cached = this.connection;
		if (cached != null) {
			if (!this.streamLivenessDisabled && this.options.isTransportLive?.() === true) {
				return cached;
			}
			if (
				!this.healthTtlDisabled &&
				this.options.timing.clock.monotonicNow() - this.lastHealthyAtMs < HEALTH_PROBE_TTL_MS
			) {
				return cached;
			}
			const epochAtProbe = this.healthEpoch;
			if (
				(await fetchHealth(
					this.options.timing,
					cached.baseUrl,
					cached.headers,
					this.options.onReachability,
				)) != null
			) {
				if (epochAtProbe === this.healthEpoch) {
					this.lastHealthyAtMs = this.options.timing.clock.monotonicNow();
				}
				return cached;
			}
		}
		const epochAtConnect = this.healthEpoch;
		let attempt = this.getOrStartConnectionAttempt(epochAtConnect);
		for (;;) {
			try {
				const connection = await this.awaitAttempt(attempt, signal);
				const supersedingAttempt = this.latestConnectionAttempt;
				if (attempt.healthEpoch !== this.healthEpoch) {
					attempt = this.getLatestAttemptForCurrentEpoch();
					continue;
				}
				if (supersedingAttempt !== attempt) {
					if (supersedingAttempt == null) {
						throw new Error("latest gateway connection attempt is missing");
					}
					attempt = supersedingAttempt;
					continue;
				}
				this.connection = connection;
				this.lastHealthyAtMs = Number.NEGATIVE_INFINITY;
				return connection;
			} catch (error) {
				const supersedingAttempt = this.latestConnectionAttempt;
				if (attempt.healthEpoch !== this.healthEpoch) {
					attempt = this.getLatestAttemptForCurrentEpoch();
					continue;
				}
				if (supersedingAttempt === attempt || supersedingAttempt == null) {
					throw error;
				}
				attempt = supersedingAttempt;
			}
		}
	}
}
