/** Returns an Error message or stringifies a non-Error throw. */
export function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

/**
 * Returns a path-safe error class and optional fs/SQLite code for logs.
 * Never includes the message, stack, or path.
 */
export function errorLogTag(error: unknown): string {
	if (!(error instanceof Error)) return typeof error;
	const code = (error as { readonly code?: string }).code;
	return code != null && code.length > 0 ? `${error.name} (${code})` : error.name;
}
