import type { CoordinatorServedMethods } from "../../shared/rpc/coordinator-main.js";
import {
	COORDINATOR_UNKNOWN_METHOD,
	type CoordinatorReplyOutcome,
} from "../../shared/rpc/coordinator-port.js";
import { isCoordinatorMethod } from "../../shared/rpc/coordinator.js";
import type { CoordinatorRequestDispatch } from "../renderer-port-server.js";
import { SandGatewayCommandError } from "./gateway-client.js";
import { SandGatewayUnreachableError } from "./gateway-reachability.js";

export const GATEWAY_COMMAND_FAILED = "gateway-command-failed";
export const GATEWAY_UNREACHABLE = "gateway-unreachable";
export const GATEWAY_TRANSPORT_FAILED = "gateway-transport-failed";

export type GatewayDispatchMembership = (
	name: string,
) => name is keyof CoordinatorServedMethods & string;

export interface GatewayCommandPort {
	dispatchCommand<M extends keyof CoordinatorServedMethods & string>(
		method: M,
		args: CoordinatorServedMethods[M]["args"],
		init?: { readonly signal?: AbortSignal },
	): Promise<CoordinatorServedMethods[M]["reply"]>;
}

function failureFor(error: unknown): {
	readonly code: string;
	readonly message: string;
	readonly transportKind?: string;
} {
	if (error instanceof SandGatewayCommandError) {
		return { code: GATEWAY_COMMAND_FAILED, message: error.message };
	}
	if (error instanceof SandGatewayUnreachableError) {
		return { code: GATEWAY_UNREACHABLE, message: error.message, transportKind: error.kind };
	}
	return {
		code: GATEWAY_TRANSPORT_FAILED,
		message: error instanceof Error ? error.message : String(error),
	};
}

export function createGatewayRequestDispatch(
	client: GatewayCommandPort,
	serves: GatewayDispatchMembership = isCoordinatorMethod,
): CoordinatorRequestDispatch {
	return async (method, args, signal): Promise<CoordinatorReplyOutcome> => {
		if (!serves(method)) {
			return {
				status: "failed",
				failure: {
					code: COORDINATOR_UNKNOWN_METHOD,
					message: `no coordinator method named ${method}`,
				},
			};
		}
		try {
			const value = await client.dispatchCommand(
				method,
				args as CoordinatorServedMethods[typeof method]["args"],
				{ signal },
			);
			return { status: "ok", value };
		} catch (error) {
			return { status: "failed", failure: failureFor(error) };
		}
	};
}
