// Classification for the desktop→box reachability path — the connect + /health +
// listAgents attempts that back the sidebar's "Can't reach your computer" state.
// It is a pure OBSERVABILITY seam: it never changes the reachability/retry
// behavior, only labels the outcome. PRIVACY: every derived field is an
// enum/timing/bounded-cause string — never a URL, token, prompt, or code data.

import { DeadlineExceededError } from "@sand/dune/scheduling";

import {
	GATEWAY_ACCESS_DENIED_MESSAGE_MARKER,
	GATEWAY_NO_STORAGE_MESSAGE_MARKER,
	hasSandBoxBlockedMarker,
	type SandGatewayBaseUrlKind,
	type SandGatewayReachabilityOutcome,
	type SandGatewayReachabilityReport,
} from "../../shared/gateway-reachability.js";
import { findSystemErrno } from "../../shared/system-errno.js";

// A FAILURE outcome (everything but `ok`) — the kind carried by the typed
// SandGatewayUnreachableError so a caller / the telemetry can tell the cause
// apart instead of the bare error that collapsed them.
export type SandGatewayUnreachableKind = Exclude<SandGatewayReachabilityOutcome, "ok">;

// Where a finished reachability report is delivered. Injected into the gateway
// client + host supervisor so they stay decoupled from the telemetry egress
// (the coordinator's composition wires this to the control port's
// reportGatewayReachability command).
export type SandGatewayReachabilitySink = (
	report: SandGatewayReachabilityReport,
	baseUrl?: string,
) => void;

// A reachability failure carried OUT of the gateway client as a typed error, so
// the roster path (and the reachability telemetry) can tell pod-unreachable /
// http-5xx / timeout / refused apart instead of the bare Error / raw fetch
// rejection that collapsed them. Parallels SandBoxDaemonUnreachableError (the
// in-box exec-daemon side, host/ports/box.ts).
//
// DISTINCT from SandGatewayCommandError: that class is a gateway REPLY (a <500
// application error the gateway decided and whose message feeds a user dialog),
// which must never be reclassified as unreachable and is never retried by the
// send path. This class is only the TRANSPORT/5xx unreachable failures, so
// wrapping them changes no existing behavior branch (nothing does `instanceof`
// on the transport failures, and the send path uses its own inline fetch, not
// the request() this is thrown from). The message embeds the kind as
// `... unreachable (<kind>)` so a coarse class survives the port boundary to the
// renderer, which can't see the subclass.
export class SandGatewayUnreachableError extends Error {
	readonly kind: SandGatewayUnreachableKind;
	readonly httpStatus?: number;
	readonly causeSummary?: string;

	constructor(
		kind: SandGatewayUnreachableKind,
		message: string,
		options?: {
			readonly httpStatus?: number;
			readonly causeSummary?: string;
			readonly cause?: unknown;
		},
	) {
		super(message, options?.cause !== undefined ? { cause: options.cause } : undefined);
		this.name = "SandGatewayUnreachableError";
		this.kind = kind;
		if (options?.httpStatus !== undefined) this.httpStatus = options.httpStatus;
		if (options?.causeSummary !== undefined) this.causeSummary = options.causeSummary;
	}
}

// A >=500 status is an infra/reachability failure -> http_5xx. A 401/403 is an
// auth/entitlement gate -> access_denied (SAND-1059: no longer `network`, not
// retryable). Any other <500 non-ok status is a gateway REPLY (application
// error, feeds a dialog), so undefined keeps the SandGatewayCommandError path.
export function outcomeForHttpStatus(status: number): "http_5xx" | "access_denied" | undefined {
	if (status >= 500) return "http_5xx";
	if (status === 401 || status === 403) return "access_denied";
	return undefined;
}

// undici's own connect/headers/body deadlines don't carry a system ETIMEDOUT
// errno (so the shared errno walk misses them). A hung generic command has no
// AbortController of its own, so undici's default headers timeout is what finally
// fires — the roster-fetch-hang fingerprint. The coordinator's own deadlines are
// the named Dune policies, which abort with a DeadlineExceededError reason (the
// shape undici then rejects with) or reject with it directly; a raw
// AbortController deadline surfaces as an "AbortError". Walk the cause chain
// for any of those shapes.
function hasFetchTimeoutSignal(error: unknown): boolean {
	const seen = new Set<unknown>();
	let current: unknown = error;
	while (current != null && typeof current === "object" && !seen.has(current)) {
		if (current instanceof DeadlineExceededError) return true;
		seen.add(current);
		const node = current as { name?: unknown; code?: unknown; cause?: unknown };
		if (
			typeof node.name === "string" &&
			(node.name === "AbortError" ||
				node.name === "TimeoutError" ||
				/TimeoutError$/.test(node.name))
		) {
			return true;
		}
		if (typeof node.code === "string" && /TIMEOUT/.test(node.code)) return true;
		current = node.cause;
	}
	return false;
}

function hasMarkerInCauseChain(error: unknown, matches: (message: string) => boolean): boolean {
	const seen = new Set<unknown>();
	let current: unknown = error;
	while (current != null && typeof current === "object" && !seen.has(current)) {
		seen.add(current);
		const node = current as { message?: unknown; cause?: unknown };
		if (typeof node.message === "string" && matches(node.message)) {
			return true;
		}
		current = node.cause;
	}
	return false;
}

// Classify a THROWN fetch/transport failure (a rejected fetch, an aborted
// request, or a connect-resolve throw) into a reachability failure kind + a
// bounded cause summary. Reuses the shared errno walk (findSystemErrno) so a
// wrapping TypeError/ConnectError is seen through to the real transport errno.
// Never inspects code data.
export function classifyGatewayFetchFailure(error: unknown): {
	outcome: SandGatewayUnreachableKind;
	causeSummary: string;
} {
	const errno = findSystemErrno(error);
	const name = error instanceof Error ? error.name : "";
	const causeSummary =
		[name, errno].filter((part) => part != null && part.length > 0).join("/") || "unknown";
	if (
		hasMarkerInCauseChain(error, (message) => message.includes(GATEWAY_NO_STORAGE_MESSAGE_MARKER))
	) {
		return { outcome: "no_storage", causeSummary };
	}
	if (hasMarkerInCauseChain(error, hasSandBoxBlockedMarker)) {
		return { outcome: "box_blocked", causeSummary };
	}
	if (
		hasMarkerInCauseChain(error, (message) =>
			message.includes(GATEWAY_ACCESS_DENIED_MESSAGE_MARKER),
		)
	) {
		return { outcome: "access_denied", causeSummary };
	}
	if (errno === "ECONNREFUSED") return { outcome: "refused", causeSummary };
	if (errno === "ENOTFOUND" || errno === "EAI_AGAIN") {
		return { outcome: "dns", causeSummary };
	}
	if (errno === "ETIMEDOUT" || hasFetchTimeoutSignal(error)) {
		return { outcome: "timeout", causeSummary };
	}
	return { outcome: "network", causeSummary };
}

export interface StreamDownClassification {
	readonly reason: string;
	readonly cause: string | null;
}

export function classifyStreamDown(input: {
	readonly stalled: boolean;
	readonly forced: boolean;
	readonly devInducedOffline: boolean;
	readonly clientPaused: boolean;
	readonly error: unknown;
}): StreamDownClassification {
	if (input.clientPaused) return { reason: "box_blocked", cause: "client-paused" };
	if (input.stalled) return { reason: "stall-timeout", cause: null };
	if (input.forced || input.devInducedOffline) {
		return {
			reason: "forced-reconnect",
			cause: input.devInducedOffline ? "dev-induced-offline" : null,
		};
	}
	const classified = classifyGatewayFetchFailure(input.error);
	return { reason: classified.outcome, cause: classified.causeSummary };
}

// Normalize ANY thrown reachability error into one shape: read the kind / http
// status / cause off an already-typed SandGatewayUnreachableError (the 5xx path),
// else classify a raw fetch/transport failure. Used at the gateway-client throw
// sites so a 5xx and a transport reject report the same fields.
export function classifyGatewayError(error: unknown): {
	outcome: SandGatewayUnreachableKind;
	httpStatus?: number;
	causeSummary?: string;
} {
	if (error instanceof SandGatewayUnreachableError) {
		const classified: {
			outcome: SandGatewayUnreachableKind;
			httpStatus?: number;
			causeSummary?: string;
		} = { outcome: error.kind };
		if (error.httpStatus !== undefined) classified.httpStatus = error.httpStatus;
		if (error.causeSummary !== undefined) classified.causeSummary = error.causeSummary;
		return classified;
	}
	return classifyGatewayFetchFailure(error);
}

// Classify a base URL as loopback vs pod-proxy WITHOUT logging the URL. Uses the
// URL constructor (never regex host stripping). "unknown" for an absent/invalid
// URL (a connection that never resolved).
export function classifyBaseUrlKind(baseUrl: string | undefined): SandGatewayBaseUrlKind {
	if (baseUrl == null || baseUrl.length === 0) return "unknown";
	try {
		const host = new URL(baseUrl).hostname;
		return host === "127.0.0.1" || host === "localhost" || host === "::1" || host === "[::1]"
			? "loopback"
			: "pod_proxy";
	} catch {
		return "unknown";
	}
}
