/**
 * Terminal or pending outcome of one accepted prompt dispatch. `pending`
 * means the Host accepted and durably recorded the send but its turn has not
 * reached a terminal state; `not-found` is only ever a status-query answer,
 * never a stored state. Acceptance is keyed by account slot and client nonce,
 * and the Host persists it before returning or emitting the authoritative echo.
 */
export type PromptAcceptanceStatus = "accepted" | "rejected" | "pending";

/**
 * Durable nonce record. The digest is immutable, and `echoEntryId` names
 * the authoritative transcript row when available.
 */
export interface PromptAcceptanceRecord {
	readonly accountSlot: string;
	readonly clientNonce: string;
	readonly inputDigest: string;
	readonly status: PromptAcceptanceStatus;
	readonly acceptedAtMs: number;
	readonly agentId: string;
	readonly echoEntryId: string | null;
	/** Present only for `rejected`: the stable failure code the Host chose. */
	readonly rejectionCode: string | null;
}

/**
 * Query result for one nonce. `not-found` proves retry is safe;
 * `unknown-durability` never permits retry without transcript or user
 * reconciliation; `found` carries the durable record.
 */
export type PromptAcceptanceLookup =
	| { readonly outcome: "not-found" }
	| { readonly outcome: "unknown-durability" }
	| { readonly outcome: "found"; readonly record: PromptAcceptanceRecord };

/**
 * Reply for one acceptance-status query. `supported: false` means the
 * connected Host does not serve `sendAcceptanceV1`; transport failures reject
 * instead of masquerading as this verdict.
 */
export type PromptAcceptanceStatusBridgeReply =
	| { readonly supported: false }
	| {
			readonly supported: true;
			readonly lookup: PromptAcceptanceLookup;
	  };

/** Protocol failure code for a nonce reused with a different digest. */
export const NONCE_DIGEST_MISMATCH = "send/nonce-digest-mismatch";

/** Single-account protocol slot shared by Host records and Client status queries. */
export const HOST_ACCOUNT_SLOT = "host";

/**
 * Capability fact advertised by Hosts that keep the durable acceptance
 * ledger. A laptop never retries a send against a Host without it, because
 * only a deduping Host makes the retry idempotent.
 */
export const SEND_ACCEPTANCE_V1 = "sendAcceptanceV1";

export const DISABLE_SEND_ACCEPT_RETURN_ENV = "SAND_DISABLE_SEND_ACCEPT_RETURN";
