import { randomUUID } from "node:crypto";
import { Resolver, lookup } from "node:dns/promises";

import {
	createDeadlinePolicy,
	DeadlineExceededError,
	type DeadlinePolicy,
	realClock,
	type Clock,
} from "@sand/dune/scheduling";

import type {
	SandGatewayDnsCluster,
	SandGatewayDnsDiagnosis,
	SandGatewayDnsDiagnosticReport,
	SandGatewayDnsProbeResult,
	SandGatewayDnsTrigger,
	SandGatewayReachabilityReport,
} from "../../shared/gateway-reachability.js";
import { findSystemErrno } from "../../shared/system-errno.js";

const DNS_PROBE_TIMEOUT_MS = 2_000;
const DNS_PROBE_MIN_INTERVAL_MS = 60_000;
const GENERAL_CONTROL_HOSTNAME = "api2.cursor.sh";

interface GatewayDnsTarget {
	readonly endpointHostname: string;
	readonly wildcardHostname: string;
	readonly cluster: SandGatewayDnsCluster;
}

export interface GatewayDnsDiagnosticOptions {
	readonly clock: Pick<Clock, "monotonicNow">;
	readonly deadline: DeadlinePolicy;
	readonly systemLookup: (hostname: string) => Promise<unknown>;
	readonly independentLookup: (hostname: string) => Promise<unknown>;
	readonly createWildcardLabel: () => string;
	readonly onDiagnostic: (report: SandGatewayDnsDiagnosticReport) => void;
}

function isAllowedCluster(value: string): value is SandGatewayDnsCluster {
	return value === "dev4" || value === "us8";
}

function dnsTargetFromBaseUrl(
	baseUrl: string | undefined,
	createWildcardLabel: () => string,
): GatewayDnsTarget | undefined {
	if (baseUrl == null) return undefined;
	try {
		const url = new URL(baseUrl);
		const labels = url.hostname.split(".");
		if (
			url.protocol !== "https:" ||
			labels.length !== 4 ||
			labels[0] == null ||
			labels[0].length === 0 ||
			labels[1] == null ||
			labels[2] !== "cursorvm" ||
			labels[3] !== "com" ||
			!isAllowedCluster(labels[1])
		) {
			return undefined;
		}
		const cluster = labels[1];
		const wildcardLabel = createWildcardLabel();
		if (!/^[a-z0-9-]{1,63}$/.test(wildcardLabel)) return undefined;
		return {
			endpointHostname: url.hostname,
			wildcardHostname: `${wildcardLabel}.${cluster}.cursorvm.com`,
			cluster,
		};
	} catch {
		return undefined;
	}
}

function classifyProbeError(error: unknown): SandGatewayDnsProbeResult {
	if (error instanceof DeadlineExceededError) return "timeout";
	switch (findSystemErrno(error)) {
		case "ENOTFOUND":
		case "ENODATA":
			return "not_found";
		case "EAI_AGAIN":
		case "ESERVFAIL":
		case "EREFUSED":
			return "temporary_failure";
		case "ETIMEOUT":
		case "ETIMEDOUT":
			return "timeout";
		default:
			return "error";
	}
}

export function classifyDnsDiagnosis(results: {
	readonly systemExact: SandGatewayDnsProbeResult;
	readonly independentExact: SandGatewayDnsProbeResult;
	readonly independentWildcard: SandGatewayDnsProbeResult;
	readonly independentGeneral: SandGatewayDnsProbeResult;
}): SandGatewayDnsDiagnosis {
	if (results.systemExact === "resolved" && results.independentExact === "resolved") {
		return "resolved_before_probe";
	}
	if (results.systemExact !== "resolved" && results.independentExact === "resolved") {
		return "system_path_failure";
	}
	if (results.systemExact === "resolved" && results.independentExact !== "resolved") {
		return "independent_path_failure";
	}
	if (results.independentExact !== "resolved" && results.independentWildcard === "resolved") {
		return "endpoint_failure";
	}
	if (
		results.independentExact !== "resolved" &&
		results.independentWildcard !== "resolved" &&
		results.independentGeneral === "resolved"
	) {
		return "cursorvm_failure";
	}
	if (results.independentGeneral !== "resolved") return "general_dns_failure";
	return "inconclusive";
}

function triggerFromCause(causeSummary: string | undefined): SandGatewayDnsTrigger {
	if (causeSummary?.includes("ENOTFOUND") === true) return "not_found";
	if (causeSummary?.includes("EAI_AGAIN") === true) return "temporary_failure";
	return "unknown";
}

export class GatewayDnsDiagnosticReporter {
	private episodeActive = false;
	private probeInFlight = false;
	private lastProbeStartedAtMs = Number.NEGATIVE_INFINITY;

	constructor(private readonly options: GatewayDnsDiagnosticOptions) {}

	observe(report: SandGatewayReachabilityReport, baseUrl?: string): void {
		if (report.outcome === "ok") {
			this.episodeActive = false;
			return;
		}
		if (report.outcome !== "dns" || this.episodeActive) return;

		const target = dnsTargetFromBaseUrl(baseUrl, this.options.createWildcardLabel);
		if (target == null) return;

		const now = this.options.clock.monotonicNow();
		if (this.probeInFlight || now - this.lastProbeStartedAtMs < DNS_PROBE_MIN_INTERVAL_MS) {
			return;
		}
		this.episodeActive = true;
		this.probeInFlight = true;
		this.lastProbeStartedAtMs = now;
		void this.run(target, triggerFromCause(report.causeSummary)).then(
			(diagnostic) => {
				this.probeInFlight = false;
				try {
					this.options.onDiagnostic(diagnostic);
				} catch {
					return;
				}
			},
			() => {
				this.probeInFlight = false;
			},
		);
	}

	private async run(
		target: GatewayDnsTarget,
		trigger: SandGatewayDnsTrigger,
	): Promise<SandGatewayDnsDiagnosticReport> {
		const probe = async (resolve: () => Promise<unknown>): Promise<SandGatewayDnsProbeResult> => {
			try {
				await this.options.deadline.run(() => resolve());
				return "resolved";
			} catch (error) {
				return classifyProbeError(error);
			}
		};
		const [systemExact, independentExact, independentWildcard, independentGeneral] =
			await Promise.all([
				probe(() => this.options.systemLookup(target.endpointHostname)),
				probe(() => this.options.independentLookup(target.endpointHostname)),
				probe(() => this.options.independentLookup(target.wildcardHostname)),
				probe(() => this.options.independentLookup(GENERAL_CONTROL_HOSTNAME)),
			]);
		const results = {
			systemExact,
			independentExact,
			independentWildcard,
			independentGeneral,
		};
		return {
			cluster: target.cluster,
			trigger,
			diagnosis: classifyDnsDiagnosis(results),
			...results,
		};
	}
}

export function createGatewayDnsDiagnosticReporter(
	onDiagnostic: (report: SandGatewayDnsDiagnosticReport) => void,
): GatewayDnsDiagnosticReporter {
	const resolver = new Resolver({ timeout: DNS_PROBE_TIMEOUT_MS, tries: 1 });
	return new GatewayDnsDiagnosticReporter({
		clock: realClock,
		deadline: createDeadlinePolicy({
			name: "gateway-dns-diagnostic",
			timeoutMs: DNS_PROBE_TIMEOUT_MS,
		}),
		systemLookup: (hostname) => lookup(hostname),
		independentLookup: (hostname) => resolver.resolve4(hostname),
		createWildcardLabel: () => `sand-dns-probe-${randomUUID()}`,
		onDiagnostic,
	});
}
