// Walk an error's `.cause` chain for a Node system errno. ConnectError uses a
// numeric `.code`, undici wraps fetch errors in `.cause`, and undici's own
// `UND_ERR_*` codes do not match the `E[A-Z_]+` system-errno shape.
export function findSystemErrno(error: unknown): string | undefined {
	const seen = new Set<unknown>();
	let current: unknown = error;
	while (current != null && typeof current === "object" && !seen.has(current)) {
		seen.add(current);
		const code = (current as { code?: unknown }).code;
		if (typeof code === "string" && /^E[A-Z_]+$/.test(code)) return code;
		current = (current as { cause?: unknown }).cause;
	}
	return undefined;
}
