import type { PollingPolicy, RetryPolicy } from "@sand/dune/scheduling";

import type { SandGatewayConnectionInfo } from "../../shared/gateway-connection.js";
import {
	GATEWAY_WEBAUTHN_REQUESTS_PATH,
	GATEWAY_WEBAUTHN_RESPONSES_PATH,
	type SandWebAuthnCeremonyRequest,
	type SandWebAuthnCeremonyResult,
	type SandWebAuthnDesktopStage,
	type SandWebAuthnRequestFrame,
	type SandWebAuthnResponseBatch,
	type SandWebAuthnResponseFrame,
} from "../../shared/webauthn-gateway.js";
import { SseBlockDecoder } from "../gateway/sse-block-decoder.js";

export interface WebAuthnApprovedPrompt {
	readonly promptId: string | null;
	readonly windowHandle?: number;
}

export interface WebAuthnSigner {
	sign(
		ceremony: SandWebAuthnCeremonyRequest,
		signal: AbortSignal,
		approved?: WebAuthnApprovedPrompt,
	): Promise<SandWebAuthnCeremonyResult>;
}

// Defeats a forged origin, not a relay using the real one: nothing in an
// assertion binds it to a browser session. See the README.
export interface WebAuthnConsent {
	requestConsent(
		ceremony: SandWebAuthnCeremonyRequest,
		signal: AbortSignal,
	): Promise<{
		readonly approved: boolean;
		readonly promptId: string | null;
		readonly windowHandle?: number;
	}>;
	reportProgress(status: string): void;
	finish(): void;
}

export interface WebAuthnProviderOptions {
	readonly resolveConnection: () => Promise<SandGatewayConnectionInfo>;
	readonly signer: WebAuthnSigner;
	readonly consent?: WebAuthnConsent;
	readonly heartbeatPolicy: PollingPolicy;
	readonly reconnectPolicy: RetryPolicy;
	readonly deliveryPolicy?: RetryPolicy;
	readonly computerId?: string;
	readonly label?: string;
	readonly log?: (message: string) => void;
}

class WebAuthnChannelError extends Error {
	readonly name = "WebAuthnChannelError";
}

export interface WebAuthnProvider {
	start(): void;
	stop(): void;
}

export function createWebAuthnProvider(options: WebAuthnProviderOptions): WebAuthnProvider {
	const log = options.log ?? (() => {});
	let lifetime: AbortController | undefined;
	let providerId: string | undefined;
	const inFlight = new Map<string, AbortController>();

	function headersFor(connection: SandGatewayConnectionInfo): Record<string, string> {
		return {
			...(connection.headers ?? {}),
			...(connection.token === undefined ? {} : { authorization: `Bearer ${connection.token}` }),
		};
	}

	async function postFrames(
		connection: SandGatewayConnectionInfo,
		frames: readonly SandWebAuthnResponseFrame[],
		signal?: AbortSignal,
	): Promise<void> {
		// Omitted, not undefined: target projects use exactOptionalPropertyTypes.
		const batch: SandWebAuthnResponseBatch =
			providerId === undefined ? { frames } : { providerId, frames };
		const response = await fetch(`${connection.baseUrl}${GATEWAY_WEBAUTHN_RESPONSES_PATH}`, {
			method: "POST",
			headers: {
				...headersFor(connection),
				"content-type": "application/json",
			},
			body: JSON.stringify(batch),
			...(signal === undefined ? {} : { signal }),
		});
		if (!response.ok) {
			throw new WebAuthnChannelError(`webauthn response POST rejected: HTTP ${response.status}`);
		}
	}

	async function runCeremony(
		connection: SandGatewayConnectionInfo,
		requestId: string,
		ceremony: SandWebAuthnCeremonyRequest,
	): Promise<void> {
		const attempt = new AbortController();
		inFlight.set(requestId, attempt);
		log(`ceremony ${requestId}: ${ceremony.kind} for ${ceremony.origin}`);
		let failedStageIfThrown: SandWebAuthnDesktopStage =
			options.consent === undefined
				? { stage: "sign", outcome: "failed" }
				: { stage: "grant", outcome: "failed" };
		let frames: readonly SandWebAuthnResponseFrame[];
		try {
			const consent = await options.consent?.requestConsent(ceremony, attempt.signal);
			if (consent !== undefined && !consent.approved) {
				await postFrames(connection, [
					{ kind: "stage", requestId, stage: "grant", outcome: "declined" },
					{
						kind: "error",
						requestId,
						name: "NotAllowedError",
						message: "The security key request was declined on your computer.",
					},
				]);
				inFlight.delete(requestId);
				return;
			}
			if (consent !== undefined) {
				failedStageIfThrown = { stage: "sign", outcome: "failed" };
				await postFrames(
					connection,
					[{ kind: "stage", requestId, stage: "grant", outcome: "ok" }],
					attempt.signal,
				).catch((error) => log(`grant stage frame failed: ${String(error)}`));
			}
			if (attempt.signal.aborted) {
				return;
			}
			const result = await options.signer.sign(ceremony, attempt.signal, consent);
			if (result.ok) {
				frames = [
					{ kind: "stage", requestId, stage: "sign", outcome: "ok" },
					{ kind: "result", requestId, credentialJson: result.credentialJson },
				];
			} else {
				frames = [
					{ kind: "stage", requestId, stage: "sign", outcome: "failed" },
					{
						kind: "error",
						requestId,
						name: result.error.name,
						message: result.error.message,
						...(result.error.code === undefined ? {} : { code: result.error.code }),
					},
				];
			}
		} catch (error) {
			frames = [
				{ kind: "stage", requestId, ...failedStageIfThrown },
				{
					kind: "error",
					requestId,
					name: "NotAllowedError",
					message: `the security key could not complete the request: ${
						error instanceof Error ? error.message : String(error)
					}`,
				},
			];
		} finally {
			options.consent?.finish();
			inFlight.delete(requestId);
		}
		if (attempt.signal.aborted) {
			return;
		}
		try {
			await (options.deliveryPolicy === undefined
				? postFrames(connection, frames)
				: options.deliveryPolicy.runWithRetry(
						() => postFrames(connection, frames),
						attempt.signal,
					));
		} catch (error) {
			log(`ceremony ${requestId} result could not be delivered: ${String(error)}`);
		}
	}

	function handleFrame(
		connection: SandGatewayConnectionInfo,
		frame: SandWebAuthnRequestFrame,
	): void {
		switch (frame.kind) {
			case "welcome":
				providerId = frame.providerId;
				void postFrames(connection, [
					{
						kind: "hello",
						...(options.computerId === undefined ? {} : { computerId: options.computerId }),
						...(options.label === undefined ? {} : { label: options.label }),
					},
				]).catch((error) => log(`hello frame failed: ${String(error)}`));
				break;
			case "ceremony":
				void runCeremony(connection, frame.requestId, frame.ceremony);
				break;
			case "cancel":
				inFlight.get(frame.requestId)?.abort();
				inFlight.delete(frame.requestId);
				break;
		}
	}

	async function connectOnce(signal: AbortSignal): Promise<void> {
		const connection = await options.resolveConnection();
		const response = await fetch(`${connection.baseUrl}${GATEWAY_WEBAUTHN_REQUESTS_PATH}`, {
			headers: headersFor(connection),
			signal,
		});
		if (!response.ok || response.body == null) {
			throw new WebAuthnChannelError(`webauthn request stream refused: HTTP ${response.status}`);
		}
		log("webauthn request stream open");
		providerId = undefined;

		const decoder = new SseBlockDecoder((block) => {
			for (const line of block.split("\n")) {
				if (!line.startsWith("data:")) continue;
				try {
					handleFrame(
						connection,
						JSON.parse(line.slice("data:".length).trim()) as SandWebAuthnRequestFrame,
					);
				} catch (error) {
					log(`dropped an unparseable request frame: ${String(error)}`);
				}
			}
		});

		const heartbeat = options.heartbeatPolicy.start(async () => {
			try {
				await postFrames(connection, [{ kind: "ping" }]);
			} catch (error) {
				log(`heartbeat failed: ${String(error)}`);
			}
		}, signal);

		try {
			for await (const chunk of response.body as AsyncIterable<Uint8Array>) {
				decoder.push(chunk);
			}
		} finally {
			heartbeat.dispose();
			for (const attempt of inFlight.values()) attempt.abort();
			inFlight.clear();
		}
		throw new WebAuthnChannelError("webauthn request stream closed");
	}

	return {
		start(): void {
			if (lifetime !== undefined) return;
			const controller = new AbortController();
			lifetime = controller;
			void options.reconnectPolicy
				.runWithRetry(async (_attempt, signal) => {
					await connectOnce(signal);
				}, controller.signal)
				.catch((error: unknown) => {
					if (controller.signal.aborted) return;
					log(`webauthn provider gave up: ${String(error)}`);
				});
		},
		stop(): void {
			lifetime?.abort();
			lifetime = undefined;
		},
	};
}
