import type { RpcClientOf } from "@sand/dune/rpc";
import { createPollingPolicy, type Disposable, type PollingPolicy } from "@sand/dune/scheduling";

import { SAND_CLIENT_PAUSE_REASON } from "../../shared/gateway-reachability.js";
import type { LocalExecDaemonDiscovery } from "../../shared/local-exec-daemon.js";
import type { CoordinatorControlRpcContract } from "../../shared/rpc/coordinator-control.js";
import {
	readLocalExecDaemonDiscovery,
	removeLocalExecDaemonFile,
	resolveLocalExecDaemonPaths,
	writeLocalExecDaemonConnection,
	writeLocalExecDaemonCredential,
	writeLocalExecSupervisorHeartbeat,
} from "./daemon-files.js";

export const LOCAL_EXEC_DAEMON_REFRESH_INTERVAL_MS = 30_000;
export const LOCAL_EXEC_DAEMON_RESPAWN_LIMIT = 10;

export function createLocalExecDaemonRefreshPolicy(): PollingPolicy {
	return createPollingPolicy({
		name: "local-exec-daemon-refresh",
		intervalMs: LOCAL_EXEC_DAEMON_REFRESH_INTERVAL_MS,
	});
}

export type LocalExecControlPort = Pick<
	RpcClientOf<CoordinatorControlRpcContract>,
	| "resolveGatewayConnection"
	| "mintLocalExecDaemonCredential"
	| "spawnLocalExecDaemon"
	| "terminateProcess"
	| "isProcessAlive"
>;

export type LocalExecDaemonAction =
	| { readonly kind: "adopt"; readonly pid: number }
	| { readonly kind: "replace"; readonly pid: number }
	| { readonly kind: "spawn" };

export function decideLocalExecDaemonAction(
	existing: LocalExecDaemonDiscovery | null,
): LocalExecDaemonAction {
	if (existing == null) return { kind: "spawn" };
	if ((existing.inflightCount ?? 0) > 0) return { kind: "adopt", pid: existing.pid };
	return { kind: "replace", pid: existing.pid };
}

export type LocalExecSupervisedDaemon =
	| { readonly origin: "adopted"; readonly pid: number }
	| { readonly origin: "spawned" };

export type LocalExecSupervisorState =
	| { readonly phase: "absent" }
	| { readonly phase: "adopting"; readonly pid: number }
	| { readonly phase: "replacing"; readonly pid: number }
	| { readonly phase: "active"; readonly daemon: LocalExecSupervisedDaemon }
	| { readonly phase: "failed"; readonly reason: string };

export interface LocalExecDaemonSupervisorOptions {
	readonly control: LocalExecControlPort;
	readonly dataDir: string;
	readonly isPackaged: boolean;
	readonly refreshPolicy: PollingPolicy;
}

export interface LocalExecDaemonSupervisor {
	start(): Promise<void>;
	refreshConnection(): Promise<void>;
	setPaused(paused: boolean): Promise<void>;
	state(): LocalExecSupervisorState;
	dispose(): void;
}

function failureReason(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

function isClientPauseRefusal(error: unknown): boolean {
	return error instanceof Error && error.message.includes(SAND_CLIENT_PAUSE_REASON);
}

export function createLocalExecDaemonSupervisor(
	options: LocalExecDaemonSupervisorOptions,
): LocalExecDaemonSupervisor {
	const paths = resolveLocalExecDaemonPaths(options.dataDir);
	let state: LocalExecSupervisorState = { phase: "absent" };
	let started = false;
	let credentialHandedOff = false;
	let disposed = false;
	let polling: Disposable | undefined;
	let refreshSequence = 0;
	let descriptorWrite = Promise.resolve();
	let paused = false;
	let refusedForClientPause = false;
	let pauseIntent = 0;
	let pauseTransition = Promise.resolve();

	const refreshConnection = async (): Promise<void> => {
		if (disposed || paused) return;
		const refreshId = ++refreshSequence;
		try {
			const connection = await options.control.resolveGatewayConnection({});
			const write = descriptorWrite.then(async () => {
				if (disposed || refreshId !== refreshSequence) return;
				await writeLocalExecDaemonConnection(connection, paths.connectionPath);
			});
			descriptorWrite = write.then(
				() => undefined,
				() => undefined,
			);
			await write;
			await writeLocalExecSupervisorHeartbeat(paths.supervisorHeartbeatPath);
			refusedForClientPause = false;
		} catch (error) {
			if (!isClientPauseRefusal(error)) return;
			refusedForClientPause = true;
			await retireDaemonForPause();
		}
	};

	const refreshCredential = async (): Promise<void> => {
		if (credentialHandedOff || disposed || paused) return;
		try {
			const credential = await options.control.mintLocalExecDaemonCredential({});
			if (credential == null || disposed) return;
			await writeLocalExecDaemonCredential(credential, paths.credentialPath);
			credentialHandedOff = true;
		} catch {}
	};

	const spawnDaemon = async (): Promise<void> => {
		if (paused || refusedForClientPause) return;
		await options.control.spawnLocalExecDaemon({
			env: {
				ELECTRON_RUN_AS_NODE: "1",
				SAND_PACKAGED: options.isPackaged ? "1" : "0",
			},
			logPath: paths.logPath,
		});
		state = { phase: "active", daemon: { origin: "spawned" } };
	};

	const queuePauseTransition = async (apply: () => Promise<void>): Promise<void> => {
		const intent = ++pauseIntent;
		const applied = pauseTransition.then(async () => {
			if (disposed || intent !== pauseIntent) return;
			await apply();
		});
		pauseTransition = applied.then(
			() => undefined,
			() => undefined,
		);
		await applied;
	};

	const retireDaemonWhileStillPaused = async (): Promise<void> => {
		if (paused || refusedForClientPause) await retireDaemonForPause();
	};

	const retireDaemonForPause = async (): Promise<void> => {
		refreshSequence += 1;
		try {
			const existing = await readLocalExecDaemonDiscovery(paths.discoveryPath);
			if (existing != null) await options.control.terminateProcess({ pid: existing.pid });
			await removeLocalExecDaemonFile(paths.connectionPath);
			state = { phase: "absent" };
		} catch (error) {
			state = { phase: "failed", reason: failureReason(error) };
		}
	};

	const establishDaemon = async (): Promise<void> => {
		if (paused || refusedForClientPause) return;
		try {
			const existing = await readLocalExecDaemonDiscovery(paths.discoveryPath);
			if (disposed) return;
			const action = decideLocalExecDaemonAction(existing);
			if (action.kind === "adopt") {
				state = { phase: "adopting", pid: action.pid };
				const alive = await options.control.isProcessAlive({ pid: action.pid });
				if (disposed) return;
				if (alive) {
					state = { phase: "active", daemon: { origin: "adopted", pid: action.pid } };
					return;
				}
				await spawnDaemon();
				return;
			}
			if (action.kind === "replace") {
				state = { phase: "replacing", pid: action.pid };
				await options.control.terminateProcess({ pid: action.pid });
				if (disposed) return;
			}
			await spawnDaemon();
		} catch (error) {
			state = { phase: "failed", reason: failureReason(error) };
		}
	};

	const probeDaemonForHeal = async (): Promise<"alive" | "dead" | "unknowable"> => {
		let discovery: LocalExecDaemonDiscovery | null;
		try {
			discovery = await readLocalExecDaemonDiscovery(paths.discoveryPath);
		} catch {
			return "unknowable";
		}
		if (discovery == null || disposed) return "unknowable";
		try {
			return (await options.control.isProcessAlive({ pid: discovery.pid })) ? "alive" : "dead";
		} catch {
			return "unknowable";
		}
	};

	let consecutiveRespawns = 0;
	const healDaemon = async (): Promise<void> => {
		if (paused || refusedForClientPause) {
			if ((await probeDaemonForHeal()) === "alive") {
				await queuePauseTransition(retireDaemonWhileStillPaused);
			}
			return;
		}
		if (state.phase === "absent") {
			consecutiveRespawns = 0;
			await establishDaemon();
			return;
		}
		const probed = await probeDaemonForHeal();
		if (disposed || probed === "unknowable") return;
		if (probed === "alive") {
			consecutiveRespawns = 0;
			return;
		}
		if (consecutiveRespawns >= LOCAL_EXEC_DAEMON_RESPAWN_LIMIT) {
			state = { phase: "failed", reason: "respawn limit reached" };
			return;
		}
		consecutiveRespawns += 1;
		await establishDaemon();
	};

	return {
		async start() {
			if (started || disposed) return;
			started = true;
			await refreshConnection();
			await refreshCredential();
			if (disposed) return;
			await establishDaemon();
			if (disposed) return;
			let absorbedImmediateTick = false;
			polling = options.refreshPolicy.start(async () => {
				if (!absorbedImmediateTick) {
					absorbedImmediateTick = true;
					return;
				}
				await refreshConnection();
				await refreshCredential();
				await healDaemon();
			});
		},
		refreshConnection,
		async setPaused(next) {
			if (disposed || paused === next) return;
			paused = next;
			await queuePauseTransition(async () => {
				if (next) {
					await retireDaemonForPause();
					return;
				}
				if (!started) return;
				await refreshConnection();
				await refreshCredential();
				await establishDaemon();
			});
		},
		state: () => state,
		dispose() {
			if (disposed) return;
			disposed = true;
			polling?.dispose();
			polling = undefined;
		},
	};
}
