import {
	COORDINATOR_CANCELLED,
	COORDINATOR_PROTOCOL_VERSION,
	COORDINATOR_UNKNOWN_METHOD,
	type CoordinatorFrame,
	type CoordinatorReplyOutcome,
	type CoordinatorServerFrame,
	parseCoordinatorFrame,
} from "../shared/rpc/coordinator-port.js";

export interface RendererPortEndpoint {
	post(frame: CoordinatorServerFrame): void;
	close(): void;
}

/** Resolves every accepted request to one reply outcome; never rejects. */
export type CoordinatorRequestDispatch = (
	method: string,
	args: unknown,
	signal: AbortSignal,
) => Promise<CoordinatorReplyOutcome>;

export interface RendererPortServerOptions {
	readonly dispatchRequest?: CoordinatorRequestDispatch;
	readonly onServing?: () => void;
}

export type RendererPortSettlement =
	| { readonly outcome: "shutdown-requested" }
	| { readonly outcome: "port-closed" }
	| { readonly outcome: "protocol-breach"; readonly detail: string };

export interface RendererPortServer {
	handleMessage(value: unknown): void;
	handlePortClosed(): void;
	/** Does nothing unless the session is serving. */
	postEvent(family: string, payload: unknown): void;
	readonly settled: Promise<RendererPortSettlement>;
}

type SessionPhase = "awaiting-hello" | "serving" | "settled";

export function createRendererPortServer(
	port: RendererPortEndpoint,
	options: RendererPortServerOptions = {},
): RendererPortServer {
	let phase: SessionPhase = "awaiting-hello";
	let resolveSettled: (settlement: RendererPortSettlement) => void = () => {};
	const settled = new Promise<RendererPortSettlement>((resolve) => {
		resolveSettled = resolve;
	});
	const inFlight = new Map<string, AbortController>();

	const settle = (settlement: RendererPortSettlement): void => {
		if (phase === "settled") return;
		phase = "settled";
		for (const controller of inFlight.values()) controller.abort();
		inFlight.clear();
		port.close();
		resolveSettled(settlement);
	};

	const breach = (detail: string): void => {
		if (phase === "settled") return;
		port.post({ kind: "lifecycle", phase: "shutdown", reason: "protocol-error", detail });
		settle({ outcome: "protocol-breach", detail });
	};

	const reply = (requestId: string, outcome: CoordinatorReplyOutcome): void => {
		port.post({ kind: "reply", requestId, outcome });
	};

	const dispatchRequest = (requestId: string, method: string, args: unknown): void => {
		const dispatch = options.dispatchRequest;
		if (dispatch == null) {
			reply(requestId, {
				status: "failed",
				failure: {
					code: COORDINATOR_UNKNOWN_METHOD,
					message: "no method table serves this session yet",
				},
			});
			return;
		}
		const controller = new AbortController();
		inFlight.set(requestId, controller);
		void dispatch(method, args, controller.signal).then(
			(outcome) => {
				if (phase !== "serving" || inFlight.get(requestId) !== controller) return;
				inFlight.delete(requestId);
				reply(requestId, outcome);
			},
			() => {
				breach(`request ${requestId} dispatch rejected instead of settling`);
			},
		);
	};

	const handleFrame = (frame: CoordinatorFrame): void => {
		if (frame.kind === "lifecycle" && frame.phase === "shutdown") {
			settle({ outcome: "shutdown-requested" });
			return;
		}
		if (frame.kind === "reply" || frame.kind === "event") {
			breach(`client posted a server-direction ${frame.kind} frame`);
			return;
		}
		if (frame.kind === "lifecycle" && frame.phase === "ready") {
			breach("client posted a server-direction ready frame");
			return;
		}
		if (phase === "awaiting-hello") {
			if (frame.kind !== "lifecycle") {
				breach(`${frame.kind} frame before hello`);
				return;
			}
			if (frame.protocolVersion !== COORDINATOR_PROTOCOL_VERSION) {
				breach(
					`hello.protocolVersion ${frame.protocolVersion} is not the supported ${COORDINATOR_PROTOCOL_VERSION}`,
				);
				return;
			}
			phase = "serving";
			port.post({
				kind: "lifecycle",
				phase: "ready",
				protocolVersion: COORDINATOR_PROTOCOL_VERSION,
			});
			options.onServing?.();
			return;
		}
		if (frame.kind === "lifecycle") {
			breach("hello repeated on a live session");
			return;
		}
		if (frame.kind === "request") {
			if (inFlight.has(frame.requestId)) {
				breach(`request.requestId ${frame.requestId} reused while in flight`);
				return;
			}
			dispatchRequest(frame.requestId, frame.method, frame.args);
			return;
		}
		const controller = inFlight.get(frame.requestId);
		if (controller == null) return;
		inFlight.delete(frame.requestId);
		controller.abort();
		reply(frame.requestId, {
			status: "failed",
			failure: { code: COORDINATOR_CANCELLED, message: "request cancelled" },
		});
	};

	return {
		handleMessage(value) {
			if (phase === "settled") return;
			const intake = parseCoordinatorFrame(value);
			if (!intake.accepted) {
				breach(intake.rejection.detail);
				return;
			}
			handleFrame(intake.frame);
		},
		handlePortClosed() {
			settle({ outcome: "port-closed" });
		},
		postEvent(family, payload) {
			if (phase !== "serving") return;
			port.post({ kind: "event", family, payload });
		},
		settled,
	};
}
