import type { Clock, Disposable } from "./clock.js";

export type { Disposable } from "./clock.js";

export interface TimePolicy {
	readonly name: string;
}

export interface DeadlinePolicyOptions {
	readonly name: string;
	readonly timeoutMs: number;
}

export interface DeadlinePolicy extends TimePolicy {
	run<T>(work: (signal: AbortSignal) => Promise<T>, signal?: AbortSignal): Promise<T>;
}

export class DeadlineExceededError extends Error {
	readonly code = "deadline_exceeded";

	constructor(readonly policyName: string) {
		super(`Deadline exceeded for ${policyName}`);
		this.name = "DeadlineExceededError";
	}
}

export interface Delay extends Disposable {
	readonly elapsed: Promise<void>;
}

export interface RetryPolicyOptions {
	readonly name: string;
	readonly maxAttempts: number;
	readonly initialDelayMs: number;
	readonly maxDelayMs: number;
	readonly backoffFactor?: number;
	readonly shouldRetry?: (error: unknown, attempt: number) => boolean;
}

export interface RetryPolicy extends TimePolicy {
	schedule(attempt: number, signal?: AbortSignal): Delay;
	runWithRetry<T>(
		work: (attempt: number, signal: AbortSignal) => Promise<T>,
		signal?: AbortSignal,
	): Promise<T>;
}

export interface PollingPolicyOptions {
	readonly name: string;
	readonly intervalMs: number;
}

export interface PollingPolicy extends TimePolicy {
	start(tick: () => Promise<void>, signal?: AbortSignal): Disposable;
}

export type DebouncedFunction<Arguments extends unknown[]> = ((...args: Arguments) => void) &
	Disposable;

export interface DebouncePolicyOptions {
	readonly name: string;
	readonly delayMs: number;
}

export interface DebouncePolicy extends TimePolicy {
	wrap<Arguments extends unknown[]>(fn: (...args: Arguments) => void): DebouncedFunction<Arguments>;
}

export interface TaskBoundaryPolicyOptions {
	readonly name: string;
}

/**
 * A named wait for the current event-loop task to finish, INCLUDING every
 * microtask it queues.
 *
 * The contract, precisely: `settled()` resolves strictly after the synchronous
 * work in progress when it was called, and strictly after every microtask that
 * work queues, transitively. A promise continuation cannot express this — a
 * microtask queued before the producer's own later hops runs before them — so
 * this is the one guarantee the other policies cannot compose out of delays.
 *
 * It exists because coalescing windows need it. A consumer that batches requests
 * arriving "in one turn" has to reopen its window after the turn's whole cascade,
 * or a producer that awaits mid-turn lands outside the batch. Draining until the
 * request set is empty does NOT substitute: the drain has already committed a
 * snapshot by then, so a late arrival either ships a redundant follow-up or gets
 * discarded unsoundly.
 *
 * Deliberately narrow. This is a boundary, not a delay: there is no duration to
 * tune, and a caller that wants one wants a debounce instead.
 */
export interface TaskBoundaryPolicy extends TimePolicy {
	settled(): Promise<void>;
}

/**
 * Built on `clock.schedule(0, ...)` rather than a bare `setImmediate`, so the
 * boundary is injectable and a suite drives it through `DeterministicClock`
 * exactly like every other policy. Any macrotask satisfies the contract, because
 * the runtime drains the microtask queue before running one; the check phase
 * versus the timer phase is an I/O-ordering distinction this contract does not
 * make.
 */
export function createTaskBoundaryPolicy(
	clock: Clock,
	options: TaskBoundaryPolicyOptions,
): TaskBoundaryPolicy {
	assertName(options.name);

	return {
		name: options.name,
		settled(): Promise<void> {
			return new Promise<void>((resolve) => {
				clock.schedule(0, resolve);
			});
		},
	};
}

export function createDeadlinePolicy(clock: Clock, options: DeadlinePolicyOptions): DeadlinePolicy {
	assertName(options.name);
	assertDuration(options.timeoutMs, "timeoutMs");

	return {
		name: options.name,
		async run(work, signal) {
			if (signal?.aborted) throw abortReason(signal);

			const controller = new AbortController();
			let rejectTimeout: (error: DeadlineExceededError) => void = () => {};
			const timeout = new Promise<never>((_, reject) => {
				rejectTimeout = reject;
			});
			let rejectCancellation: (reason: unknown) => void = () => {};
			const cancellation = new Promise<never>((_, reject) => {
				rejectCancellation = reject;
			});
			let removeAbortListener = (): void => {};

			if (signal != null) {
				const abort = (): void => {
					const reason = abortReason(signal);
					rejectCancellation(reason);
					controller.abort(reason);
				};
				signal.addEventListener("abort", abort, { once: true });
				removeAbortListener = () => signal.removeEventListener("abort", abort);
			}

			const deadline = clock.schedule(options.timeoutMs, () => {
				const error = new DeadlineExceededError(options.name);
				rejectTimeout(error);
				controller.abort(error);
			});

			try {
				return await Promise.race([work(controller.signal), timeout, cancellation]);
			} finally {
				deadline.dispose();
				removeAbortListener();
			}
		},
	};
}

export function createRetryPolicy(clock: Clock, options: RetryPolicyOptions): RetryPolicy {
	assertName(options.name);
	assertPositiveInteger(options.maxAttempts, "maxAttempts");
	assertDuration(options.initialDelayMs, "initialDelayMs");
	assertDuration(options.maxDelayMs, "maxDelayMs");
	if (options.maxDelayMs < options.initialDelayMs) {
		throw new RangeError("maxDelayMs must be at least initialDelayMs");
	}
	const backoffFactor = options.backoffFactor ?? 2;
	if (!Number.isFinite(backoffFactor) || backoffFactor < 1) {
		throw new RangeError("backoffFactor must be a finite number at least 1");
	}
	const shouldRetry = options.shouldRetry ?? (() => true);

	const policy: RetryPolicy = {
		name: options.name,
		schedule(attempt, signal) {
			assertPositiveInteger(attempt, "attempt");
			// backoffFactor ** (attempt - 1) can overflow to Infinity, and a
			// zero initialDelayMs would then produce 0 * Infinity = NaN; clamp
			// the growth finite so the product stays a valid delay.
			const growth = Math.min(backoffFactor ** (attempt - 1), Number.MAX_VALUE);
			const delayMs = Math.min(options.maxDelayMs, options.initialDelayMs * growth);
			return createDelay(clock, delayMs, signal);
		},
		async runWithRetry(work, signal) {
			const workSignal = signal ?? new AbortController().signal;

			let rejectCancellation: (reason: unknown) => void = () => {};
			const cancellation = new Promise<never>((_, reject) => {
				rejectCancellation = reject;
			});
			let removeAbortListener = (): void => {};
			if (signal != null) {
				const abort = (): void => rejectCancellation(abortReason(signal));
				signal.addEventListener("abort", abort, { once: true });
				removeAbortListener = () => signal.removeEventListener("abort", abort);
			}

			try {
				for (let attempt = 1; ; attempt += 1) {
					if (signal?.aborted) throw abortReason(signal);
					try {
						return await Promise.race([work(attempt, workSignal), cancellation]);
					} catch (error) {
						if (signal?.aborted) throw abortReason(signal);
						if (attempt >= options.maxAttempts || !shouldRetry(error, attempt)) {
							throw error;
						}

						const delay = policy.schedule(attempt, signal);
						try {
							await delay.elapsed;
						} finally {
							delay.dispose();
						}
					}
				}
			} finally {
				removeAbortListener();
			}
		},
	};

	return policy;
}

export function createPollingPolicy(clock: Clock, options: PollingPolicyOptions): PollingPolicy {
	assertName(options.name);
	assertDuration(options.intervalMs, "intervalMs");
	if (options.intervalMs === 0) {
		throw new RangeError("intervalMs must be greater than 0");
	}

	return {
		name: options.name,
		start(tick, signal) {
			let active = true;
			let scheduled: Disposable | undefined;
			let removeAbortListener = (): void => {};

			const dispose = (): void => {
				if (!active) return;
				active = false;
				scheduled?.dispose();
				scheduled = undefined;
				removeAbortListener();
			};

			const run = (): void => {
				scheduled = undefined;
				if (!active) return;

				let completion: Promise<void>;
				try {
					completion = tick();
				} catch {
					dispose();
					return;
				}

				void completion.then(
					() => {
						if (!active) return;
						scheduled = clock.schedule(options.intervalMs, run);
					},
					() => dispose(),
				);
			};

			const polling = { dispose };
			if (signal?.aborted) {
				dispose();
				return polling;
			}
			if (signal != null) {
				signal.addEventListener("abort", dispose, { once: true });
				removeAbortListener = () => signal.removeEventListener("abort", dispose);
			}

			run();
			return polling;
		},
	};
}

export function createDebouncePolicy(clock: Clock, options: DebouncePolicyOptions): DebouncePolicy {
	assertName(options.name);
	assertDuration(options.delayMs, "delayMs");

	const wrap = <Arguments extends unknown[]>(
		fn: (...args: Arguments) => void,
	): DebouncedFunction<Arguments> => {
		let active = true;
		let scheduled: Disposable | undefined;

		return Object.assign(
			(...args: Arguments): void => {
				if (!active) return;
				scheduled?.dispose();
				scheduled = clock.schedule(options.delayMs, () => {
					scheduled = undefined;
					fn(...args);
				});
			},
			{
				dispose(): void {
					if (!active) return;
					active = false;
					scheduled?.dispose();
					scheduled = undefined;
				},
			},
		);
	};

	return {
		name: options.name,
		wrap,
	};
}

export interface IdleWatchdogPolicyOptions {
	readonly name: string;
	readonly idleMs: number;
}

export interface IdleWatchdogHandle extends Disposable {
	kick(): void;
}

export interface IdleWatchdogPolicy extends TimePolicy {
	arm(onIdle: () => void): IdleWatchdogHandle;
}

export interface ExpiryPolicyOptions {
	readonly name: string;
	readonly ttlMs: number;
}

export interface ExpiryPolicy extends TimePolicy {
	arm(key: string, onExpire: () => void): Disposable;
}

export function createIdleWatchdogPolicy(
	clock: Clock,
	options: IdleWatchdogPolicyOptions,
): IdleWatchdogPolicy {
	assertName(options.name, "name");
	assertDuration(options.idleMs, "idleMs");

	return {
		name: options.name,
		arm(onIdle) {
			let active = true;
			let scheduled: Disposable | undefined;

			const rearm = (): void => {
				scheduled?.dispose();
				scheduled = clock.schedule(options.idleMs, () => {
					scheduled = undefined;
					onIdle();
				});
			};

			rearm();
			return {
				kick(): void {
					if (!active) return;
					rearm();
				},
				dispose(): void {
					if (!active) return;
					active = false;
					scheduled?.dispose();
					scheduled = undefined;
				},
			};
		},
	};
}

export function createExpiryPolicy(clock: Clock, options: ExpiryPolicyOptions): ExpiryPolicy {
	assertName(options.name, "name");
	assertDuration(options.ttlMs, "ttlMs");

	const pending = new Map<string, Disposable>();

	return {
		name: options.name,
		arm(key, onExpire) {
			pending.get(key)?.dispose();
			const scheduled = clock.schedule(options.ttlMs, () => {
				pending.delete(key);
				onExpire();
			});
			pending.set(key, scheduled);

			return {
				dispose(): void {
					const isCurrentArming = pending.get(key) === scheduled;
					if (!isCurrentArming) return;
					pending.delete(key);
					scheduled.dispose();
				},
			};
		},
	};
}

function createDelay(clock: Clock, delayMs: number, signal?: AbortSignal): Delay {
	let settled = false;
	let resolveElapsed: () => void = () => {};
	let rejectElapsed: (reason: unknown) => void = () => {};
	const elapsed = new Promise<void>((resolve, reject) => {
		resolveElapsed = resolve;
		rejectElapsed = reject;
	});
	void elapsed.catch(() => {});
	let removeAbortListener = (): void => {};

	const scheduled = clock.schedule(delayMs, () => {
		if (settled) return;
		settled = true;
		removeAbortListener();
		resolveElapsed();
	});

	const cancel = (reason: unknown): void => {
		if (settled) return;
		settled = true;
		scheduled.dispose();
		removeAbortListener();
		rejectElapsed(reason);
	};

	if (signal?.aborted) {
		cancel(abortReason(signal));
	} else if (signal != null) {
		const abort = (): void => cancel(abortReason(signal));
		signal.addEventListener("abort", abort, { once: true });
		removeAbortListener = () => signal.removeEventListener("abort", abort);
	}

	return {
		elapsed,
		dispose: () => cancel(createAbortError()),
	};
}

function abortReason(signal: AbortSignal): unknown {
	return signal.reason ?? createAbortError();
}

function createAbortError(): Error {
	const error = new Error("Operation aborted");
	error.name = "AbortError";
	return error;
}

function assertName(name: string, field: string = "name"): void {
	if (name.trim().length === 0) {
		throw new TypeError(`${field} must not be empty`);
	}
}

function assertDuration(value: number, name: string): void {
	if (!Number.isFinite(value) || value < 0) {
		throw new RangeError(`${name} must be a finite non-negative number`);
	}
}

function assertPositiveInteger(value: number, name: string): void {
	if (!Number.isInteger(value) || value < 1) {
		throw new RangeError(`${name} must be a positive integer`);
	}
}
