const PERMANENT_REFUSAL_KINDS: ReadonlySet<SandGatewayUnreachableKind> = new Set([
	"no_storage",
	"box_blocked",
]);

export const SSE_RECONNECT_MIN_MS = 1_000;
export const SSE_RECONNECT_MAX_MS = 10_000;

// The host emits an SSE heartbeat (":ping") every 15s (SSE_HEARTBEAT_MS in
// gateway-server), so a healthy stream always delivers *some* bytes well within
// this window. If nothing arrives for this long the connection is treated as
// silently dead — a half-open socket (after the machine sleeps/wakes) or a
// wedged host never sends a FIN, so an untimed read would otherwise hang here
// forever — and is aborted to force a reconnect. Kept comfortably above two
// heartbeat intervals to avoid aborting a merely slow stream.
export const SSE_STALL_TIMEOUT_MS = 35_000;

// The counterpart to the stall watchdog for the CONNECT handshake, which the
// stall watchdog does NOT cover (it arms once the stream is live). Without
// this the connect is bounded only by undici's minutes-long headersTimeout,
// and a box rescheduled behind the anyrun pod proxy commonly leaves a
// half-open connection: the TCP handshake completes but headers never come,
// parking the SINGLE reconnect loop — no retry, no backoff, and no connected
// edge (the sole transport up-edge the renderer's reconnect pass keys on).
// The box recovers server-side in ~1 minute, but the desktop showed a
// multi-minute phantom outage until the OS reset the wedged socket. Generous
// enough that a slow-but-progressing connect is never cut short; a retry is
// cheap and idempotent, so erring low is safe.
export const SSE_CONNECT_TIMEOUT_MS = 15_000;

// The gateway reports command failures as `{ "error": message }`; surfacing
// it verbatim lets user-facing host errors reach a dialog unwrapped.
function extractGatewayErrorMessage(body: string): string | null {
	try {
		const parsed = JSON.parse(body) as Partial<{ error: string }>;
		return typeof parsed.error === "string" && parsed.error.length > 0 ? parsed.error : null;
	} catch {
		return null;
	}
}

// The gateway REPLIED with an error (an HTTP error status + message): the
// request reached a live gateway and was decided there, so a transport-level
// retry is pointless (and for an application error, wrong). Distinguished from
// transport failures (connect refused / reset / timeout — a plain fetch
// rejection), which never carry this class and ARE the retryable kind for the
// idempotent send below.
export class SandGatewayCommandError extends Error {}

// Bounded deadline for the send POST. With the host resolving the send RPC at
// DURABLE ACCEPTANCE (not turn end), a healthy send completes in transport +
// a sub-ms append, so a response beyond this is a wedged connection, not a
// slow send (undici's default headers timeout is minutes, which left the
// bubble gray the whole time). Safe even against a host still kill-switched
// to await-the-turn responses: aborting never cancels the host-side turn, and
// the idempotent retry resolves fast via the host's accepted-nonce dedupe.
export const SEND_POST_TIMEOUT_MS = 15_000;
// Kill-switch (same env the host honors for its half of the contract): when
// set, the send POST goes back to the plain unbounded command path — no
// timeout, no retry. Resolved once at construction.
const DISABLE_SEND_ACCEPT_RETURN_ENV = "SAND_DISABLE_SEND_ACCEPT_RETURN";
const SEND_POST_TIMEOUT_ENV = "SAND_SEND_POST_TIMEOUT_MS";

// Bounded deadline for one BOOT-BLOCKING roster read attempt: listAgents
// (the boot gate's covering fetch) and countAgents (the first-run phase
// probe). Unbounded, a wedged box connection or an unanswered connect
// resolve parked these for minutes — the stuck "Setting up Grok Bot's computer"
// cover (SEV-1365) — while the roster store's in-flight guard blocked every
// reconnect refetch behind them. Bounded (the SSE connect bound proven on
// this same hop; ~10x a healthy probe), a wedged attempt settles and one
// idempotent retry recovers the wedged-socket case in seconds.
export const ROSTER_READ_TIMEOUT_MS = 15_000;
const ROSTER_READ_TIMEOUT_ENV = "SAND_ROSTER_READ_TIMEOUT_MS";
// Kill-switch for the slim-avatar capability advertisement: when set, gateway
// requests stop carrying GATEWAY_SLIM_AVATARS_HEADER, so the host serves
// legacy inline-avatar payloads byte-for-byte. Resolved once at construction.
const DISABLE_SLIM_AVATARS_ENV = "SAND_DISABLE_SLIM_AVATARS";

export const TRACE_WINDOW_ROOT_CACHE_MS = 5_000;

/**
 * One SSE event off the host's egress, exactly as framed on the wire: the
 * channel name and the untouched domain payload (the forever-box channel is
 * the one exception — its loopback noVNC URLs are rewritten to the
 * pod-proxied routes before any consumer sees them, exactly like the
 * forever-box command replies). The payload stays `unknown` here because it
 * is a shared contract value the port fan-out forwards byte-identically;
 * typing it per channel would put a second validator inside the boundary.
 */
export interface CoordinatorGatewaySseEvent {
	readonly channel: string;
	readonly payload: unknown;
}

/**
 * A transport lifecycle fact in the control port's frozen event shapes
 * (CoordinatorControlEvents): the coordinator emits these; Electron main
 * consumes them. `generation` is the monotonic count of ESTABLISHED streams:
 * a connected edge carries the new stream's number, and a down edge carries
 * the number of the stream that dropped (0 when forced recovery starts before
 * any stream ever established).
 *
 * Scoped to the two transport families by name: the control contract also
 * carries the agents feed (`agents-event` / `agents-roster-seed`), which the
 * COMPOSITION fans from the SSE stream — this client emits only transport
 * lifecycle facts, and widening this union would let a payload without a
 * `generation` masquerade as one.
 */
type CoordinatorTransportLifecycleFamily = "transport-connected" | "transport-down";

export type CoordinatorGatewayTransportEvent = {
	readonly [F in CoordinatorTransportLifecycleFamily]: {
		readonly family: F;
		readonly payload: CoordinatorControlEvents[F];
	};
}[CoordinatorTransportLifecycleFamily];

export type CoordinatorGatewayTransportSink = (event: CoordinatorGatewayTransportEvent) => void;

/**
 * Where one nonce-correlated send-path transport stage is delivered, in the
 * control port's frozen report shape (reportTransportStage). Injected so this
 * module never implements the telemetry egress; the composition wires it to
 * the control port and Electron main records the span (desktop-send-trace).
 */
export type CoordinatorTransportStageRecorder = (report: CoordinatorTransportStageReport) => void;

/**
 * The client's semantic time surface, injected so the lane suites drive every
 * deadline, backoff, and clock read through DeterministicClock. Production
 * composition takes createCoordinatorGatewayClientTiming below.
 */
export interface CoordinatorGatewayClientTiming {
	readonly clock: Clock;
	readonly reconnectBackoff: RetryPolicy;
	readonly connectDeadline: DeadlinePolicy;
	readonly stallWatchdog: IdleWatchdogPolicy;
	readonly sendPostDeadline: DeadlinePolicy;
	readonly rosterReadDeadline: DeadlinePolicy;
}

export function createCoordinatorGatewayClientTiming(): CoordinatorGatewayClientTiming {
	// The send and roster-read deadlines are env-tunable (ops escape hatch +
	// testability); a non-positive/invalid override falls back to the default.
	// Resolved once here: the env contract is a process-start fact.
	const overrideMs = Number(process.env[SEND_POST_TIMEOUT_ENV]);
	const sendPostTimeoutMs =
		Number.isFinite(overrideMs) && overrideMs > 0 ? overrideMs : SEND_POST_TIMEOUT_MS;
	const rosterReadOverrideMs = Number(process.env[ROSTER_READ_TIMEOUT_ENV]);
	const rosterReadTimeoutMs =
		Number.isFinite(rosterReadOverrideMs) && rosterReadOverrideMs > 0
			? rosterReadOverrideMs
			: ROSTER_READ_TIMEOUT_MS;
	return {
		clock: realClock,
		// The reconnect loop is unbounded and floor-resetting: it retries
		// forever (a box outage must never strand the desktop) and resets to
		// the floor on every established stream, so only schedule(attempt) fits
		// — runWithRetry's finite maxAttempts does not. The policy still
		// requires a bound; MAX_SAFE_INTEGER records "unbounded by design".
		reconnectBackoff: createRetryPolicy({
			name: "gateway-sse-reconnect-backoff",
			maxAttempts: Number.MAX_SAFE_INTEGER,
			initialDelayMs: SSE_RECONNECT_MIN_MS,
			maxDelayMs: SSE_RECONNECT_MAX_MS,
			backoffFactor: 2,
		}),
		connectDeadline: createDeadlinePolicy({
			name: "gateway-sse-connect",
			timeoutMs: SSE_CONNECT_TIMEOUT_MS,
		}),
		stallWatchdog: createIdleWatchdogPolicy({
			name: "gateway-sse-stall",
			idleMs: SSE_STALL_TIMEOUT_MS,
		}),
		sendPostDeadline: createDeadlinePolicy({
			name: "gateway-send-post",
			timeoutMs: sendPostTimeoutMs,
		}),
		rosterReadDeadline: createDeadlinePolicy({
			name: "gateway-roster-read",
			timeoutMs: rosterReadTimeoutMs,
		}),
	};
}

export interface CoordinatorGatewayClientOptions {
	// Resolves the live gateway connection (base URL + per-session token). Called
	// before every command and on every SSE (re)connect so a host replacement —
	// which rotates the token — is always picked up. The coordinator wires this
	// to its host supervisor, whose misses pull resolveGatewayConnection over
	// the control port.
	// `signal` is the caller's give-up edge (the SSE connect deadline's own
	// signal, a port cancel, or the roster-read deadline). The supervisor
	// treats an abort as "this connect failed", so the pull it was driving is
	// retired rather than left as the shared attempt for every later caller.
	readonly resolveConnection: (signal?: AbortSignal) => Promise<SandGatewayConnectionInfo>;
	readonly onEvent: (event: CoordinatorGatewaySseEvent) => void;
	// The transport lifecycle egress (frozen control-port event shapes). A
	// connected edge fires on every established stream; a down edge fires when
	// an ESTABLISHED stream drops (reader done, watchdog abort, or a read
	// error), or when explicit forced recovery begins while the initial connect
	// was still down. Never fired for an ordinary pre-stream connect failure or
	// on close().
	readonly onTransportEvent?: CoordinatorGatewayTransportSink;
	// Invoked before a command's single idempotent retry (the send POST's, or
	// the bounded listAgents read's), so the owner can drop any warm-connection
	// trust (the supervisor's health-probe TTL) and the retry re-probes/
	// re-resolves instead of re-POSTing blind at the endpoint that just failed.
	// Optional; tests and non-supervised clients omit it.
	readonly onTransportRetry?: () => void;
	// The injected send-path telemetry seam (see CoordinatorTransportStageRecorder).
	// Omitted (tests, non-supervised clients) means no stage recording.
	readonly recordTransportStage?: CoordinatorTransportStageRecorder;
	// Observability seam for the desktop→box reachability path: called with a
	// classified result each time a gateway command FAILS, the SSE stream
	// (re)connects or its connect FAILS. Pure telemetry — it never changes the
	// command/reconnect behavior. Omitted (tests, non-supervised clients) means no
	// reachability reporting. Never throws into the caller (the client swallows it).
	readonly onReachability?: SandGatewayReachabilitySink;
	// The staff trace window's root; null means no window, omitted never traced.
	readonly resolveTraceWindowTraceparent?: () => Promise<string | null>;
	// Main exports the client span with the report's exact ids; omitted means
	// the root is stamped instead.
	readonly recordGatewayCommandSpan?: (report: CoordinatorGatewayCommandSpanReport) => void;
	readonly timing: CoordinatorGatewayClientTiming;
}

// Applies a connection's auth to a header set: any connection-scoped headers
// (e.g. the in-box pod-proxy network token) first, then the bearer token when
// the gateway requires auth. A local loopback gateway with no token / headers
// leaves the set untouched (today's default).
function withAuth(
	headers: Record<string, string>,
	connection: Pick<SandGatewayConnectionInfo, "token" | "headers">,
): Record<string, string> {
	const merged: Record<string, string> = { ...headers, ...connection.headers };
	if (connection.token != null && connection.token.length > 0) {
		merged.authorization = `${GATEWAY_AUTH_SCHEME} ${connection.token}`;
	}
	return merged;
}

// The contract methods served by an explicit member below instead of the
// uniform POST: the latency-critical send (bounded deadline + idempotent
// retry + stage telemetry) and the box-status reads whose replies carry
// loopback noVNC URLs needing the pod-proxy rewrite. Bounded by BEHAVIOR, not
// by contract growth: a new contract entry rides the uniform path untouched.
type ForeverBoxStatusMethod = "getForeverBoxStatus" | "ensureForeverBox";

// The coordinator's typed handle to the host gateway: brain commands over HTTP
// and the brain's events over a self-healing SSE stream. The renderer reaches
// it only through the coordinator's data port, so the laptop stays a thin
// client of the host.
export class CoordinatorGatewayClient {
	private isClosed = false;
	private devInducedOffline = false;
	private clientPaused = false;
	private transportState: "initial" | "connected" | "disconnected" = "initial";
	// The event loop is single-owner: start() is idempotent, and a manual
	// reconnect interrupts whichever phase is active (stream/connect or backoff)
	// instead of spawning a competing loop.
	private eventLoopPromise: Promise<void> | undefined;
	private activeEventLoopController: AbortController | undefined;
	private reconnectGeneration = 0;
	private pendingForcedReconnect:
		| {
				readonly generation: number;
				readonly promise: Promise<void>;
				readonly resolve: () => void;
				readonly reject: (error: Error) => void;
		  }
		| undefined;
	private connectionCount = 0;
	private readonly sendAcceptReturnDisabled: boolean;
	private readonly slimAvatarsDisabled: boolean;
	private cachedTraceWindowRoot:
		| { readonly expiresAtMonotonicMs: number; readonly root: string | undefined }
		| undefined;
	private inflightTraceWindowRoot: Promise<void> | undefined;
	private spanSinkBroken = false;
	private readonly options: Omit<CoordinatorGatewayClientOptions, "resolveConnection">;
	private readonly upstreamResolveConnection: CoordinatorGatewayClientOptions["resolveConnection"];

	constructor(options: CoordinatorGatewayClientOptions) {
		const { resolveConnection, ...rest } = options;
		this.options = rest;
		this.upstreamResolveConnection = resolveConnection;
		this.sendAcceptReturnDisabled = process.env[DISABLE_SEND_ACCEPT_RETURN_ENV] === "1";
		this.slimAvatarsDisabled = process.env[DISABLE_SLIM_AVATARS_ENV] === "1";
	}

	// Every gateway request's headers: the connection's auth plus this client's
	// capability advertisements — today the slim-avatar header, which tells the
	// host to serve summaries with `avatarDataUrl: null` + `avatarVersion` so
	// roster payloads stop re-shipping inline image bytes (the client resolves
	// avatars through getAgentAvatar instead). An older host ignores it.
	private requestHeaders(
		base: Record<string, string>,
		connection: Pick<SandGatewayConnectionInfo, "token" | "headers">,
	): Record<string, string> {
		const headers = withAuth(base, connection);
		if (!this.slimAvatarsDisabled) {
			headers[GATEWAY_SLIM_AVATARS_HEADER] = "1";
		}
		return headers;
	}

	// Stale-while-revalidate, never awaited: main can never park a command.
	private traceWindowRoot(): string | undefined {
		const resolve = this.options.resolveTraceWindowTraceparent;
		if (resolve === undefined) return undefined;
		const now = this.options.timing.clock.monotonicNow();
		const cached = this.cachedTraceWindowRoot;
		const isFresh = cached !== undefined && now < cached.expiresAtMonotonicMs;
		if (!isFresh && this.inflightTraceWindowRoot === undefined) {
			const inflight = this.pullTraceWindowRoot(resolve).finally(() => {
				if (this.inflightTraceWindowRoot === inflight) {
					this.inflightTraceWindowRoot = undefined;
				}
			});
			this.inflightTraceWindowRoot = inflight;
		}
		return cached?.root;
	}

	private async pullTraceWindowRoot(resolve: () => Promise<string | null>): Promise<void> {
		try {
			const root = (await resolve()) ?? undefined;
			this.cachedTraceWindowRoot = {
				expiresAtMonotonicMs: this.options.timing.clock.monotonicNow() + TRACE_WINDOW_ROOT_CACHE_MS,
				root,
			};
		} catch {
			this.cachedTraceWindowRoot = undefined;
		}
	}

	start(): void {
		if (this.isClosed || this.eventLoopPromise != null) return;
		this.eventLoopPromise = this.runEventLoop().finally(() => {
			this.eventLoopPromise = undefined;
		});
	}

	// Tear down the current stream/connect attempt without terminally closing the
	// client, then resolve only after the one event loop has established a fresh
	// stream. Concurrent calls share one recovery so repeated Retry clicks cannot
	// stack streams. The owner invalidates its health cache before calling this,
	// making the fresh attempt re-resolve instead of trusting the endpoint whose
	// stream wedged.
	forceReconnect(): Promise<void> {
		if (this.isClosed) {
			return Promise.reject(new Error("gateway client is closed"));
		}
		if (this.pendingForcedReconnect != null) {
			this.reconnectGeneration += 1;
			this.interruptEventLoopAttempt();
			return this.pendingForcedReconnect.promise;
		}

		const { promise, resolve, reject } = Promise.withResolvers<void>();
		this.reconnectGeneration += 1;
		this.pendingForcedReconnect = {
			generation: this.reconnectGeneration,
			promise,
			resolve,
			reject,
		};
		this.interruptEventLoopAttempt();
		return promise;
	}

	private interruptEventLoopAttempt(): void {
		if (this.transportState !== "connected") this.notifyDisconnected("forced-reconnect", null);
		this.activeEventLoopController?.abort();
		this.start();
	}

	private emitTransportEvent(event: CoordinatorGatewayTransportEvent): void {
		this.options.onTransportEvent?.(event);
	}

	setDevInducedOffline(induced: boolean): { readonly induced: boolean } {
		if (this.devInducedOffline !== induced) {
			this.devInducedOffline = induced;
			this.activeEventLoopController?.abort();
		}
		return { induced: this.devInducedOffline };
	}

	setClientPaused(paused: boolean): { readonly paused: boolean } {
		if (this.clientPaused !== paused) {
			this.clientPaused = paused;
			this.activeEventLoopController?.abort();
		}
		return { paused: this.clientPaused };
	}

	private async resolveConnection(signal?: AbortSignal): Promise<SandGatewayConnectionInfo> {
		if (this.clientPaused) {
			throw new SandGatewayUnreachableError("box_blocked", SAND_CLIENT_PAUSE_BLOCKED_MESSAGE, {
				causeSummary: "client-paused",
			});
		}
		if (this.devInducedOffline) {
			throw new SandGatewayUnreachableError("network", "gateway offline: induced by dev controls", {
				causeSummary: "dev-induced-offline",
			});
		}
		return await this.upstreamResolveConnection(signal);
	}

	private notifyDisconnected(reason: string, cause: string | null): void {
		if (this.isClosed || this.transportState === "disconnected") return;
		this.transportState = "disconnected";
		this.emitTransportEvent({
			family: "transport-down",
			payload: { generation: this.connectionCount, reason, cause },
		});
	}

	close(): void {
		this.isClosed = true;
		this.activeEventLoopController?.abort();
		this.pendingForcedReconnect?.reject(new Error("gateway client closed"));
		this.pendingForcedReconnect = undefined;
	}

	// Report a classified reachability result to the observability sink, if wired.
	// Best-effort: telemetry must never throw into (or slow) the command path.
	private reportReachability(
		report: Parameters<SandGatewayReachabilitySink>[0],
		baseUrl?: string,
	): void {
		if (this.clientPaused) return;
		try {
			this.options.onReachability?.(report, baseUrl);
		} catch {}
	}

	// Deliver one nonce-correlated send stage to the injected recorder in the
	// control port's frozen shape. Stages are keyed by (accountSlot,
	// clientNonce) — the durable acceptance ledger's identity — so a nonce-less
	// legacy send records nothing (main's span pipeline is fail-closed on the
	// missing traceparent anyway). Best-effort, like reportReachability.
	private recordSendStage(stage: {
		readonly stage: "gateway-connect" | "gateway-post";
		readonly attempt: number;
		readonly clientNonce: string | undefined;
		readonly traceparent: string | undefined;
		readonly startEpochMs: number;
		readonly durationMs: number;
		readonly isError?: boolean;
	}): void {
		const recorder = this.options.recordTransportStage;
		if (recorder == null) return;
		if (stage.clientNonce == null || stage.clientNonce.length === 0) return;
		try {
			recorder({
				accountSlot: HOST_ACCOUNT_SLOT,
				clientNonce: stage.clientNonce,
				stage: stage.stage,
				attempt: stage.attempt,
				traceparent: stage.traceparent ?? null,
				startEpochMs: stage.startEpochMs,
				durationMs: stage.durationMs,
				isError: stage.isError === true,
			});
		} catch {}
	}

	private reportCommandSpan(
		method: string,
		commandTrace: { readonly root: string; readonly child: DerivedChildTraceparent } | undefined,
		settle: {
			readonly startEpochMs: number;
			readonly durationMs: number;
			readonly isError: boolean;
		},
	): void {
		if (commandTrace === undefined) return;
		const sink = this.options.recordGatewayCommandSpan;
		if (sink == null || this.spanSinkBroken) return;
		try {
			sink({
				method,
				rootTraceparent: commandTrace.root,
				spanId: commandTrace.child.spanId,
				startEpochMs: settle.startEpochMs,
				durationMs: settle.durationMs,
				isError: settle.isError,
			});
		} catch {
			this.spanSinkBroken = true;
		}
	}

	private async request<TResult>(
		method: string,
		args: object | undefined,
		init?: { readonly signal?: AbortSignal },
	): Promise<{
		readonly result: TResult;
		readonly connection: SandGatewayConnectionInfo;
	}> {
		const startMonotonicMs = this.options.timing.clock.monotonicNow();
		let connection: SandGatewayConnectionInfo | undefined;
		let commandTrace:
			| { readonly root: string; readonly child: DerivedChildTraceparent }
			| undefined;
		let fetchStartMonotonicMs = startMonotonicMs;
		let fetchStartEpochMs = 0;
		try {
			connection = await this.resolveConnection(init?.signal);
			const root = this.traceWindowRoot();
			const child =
				root !== undefined && this.options.recordGatewayCommandSpan != null
					? deriveChildTraceparent(root)
					: undefined;
			if (root !== undefined && child !== undefined) {
				commandTrace = { root, child };
			}
			const traceparent = child?.traceparent ?? root;
			fetchStartMonotonicMs = this.options.timing.clock.monotonicNow();
			fetchStartEpochMs = this.options.timing.clock.now();
			const response = await fetch(`${connection.baseUrl}${GATEWAY_API_PREFIX}/${method}`, {
				method: "POST",
				headers: this.requestHeaders(
					{
						"content-type": "application/json",
						...(traceparent !== undefined ? { [GATEWAY_TRACEPARENT_HEADER]: traceparent } : {}),
					},
					connection,
				),
				body: JSON.stringify(args ?? {}),
				...(init?.signal != null ? { signal: init.signal } : {}),
			});
			if (!response.ok) {
				const detail = await response.text().catch(() => response.statusText);
				const message = extractGatewayErrorMessage(detail) ?? `gateway ${method} failed: ${detail}`;
				// A <500 status is a gateway REPLY (an application error): keep the
				// existing SandGatewayCommandError — it feeds user dialogs verbatim and is
				// never retried, and it is NOT a reachability failure. A 5xx is an infra
				// failure (the pod proxy routed but the gateway/host errored); carry it as
				// unreachable (reported in the catch below) with the SAME message so any
				// dialog shows identical text.
				if (response.status < 500) throw new SandGatewayCommandError(message);
				throw new SandGatewayUnreachableError("http_5xx", message, {
					httpStatus: response.status,
				});
			}
			const result = (await response.json()) as TResult;
			this.reportCommandSpan(method, commandTrace, {
				startEpochMs: fetchStartEpochMs,
				durationMs: this.options.timing.clock.monotonicNow() - fetchStartMonotonicMs,
				isError: false,
			});
			return { result, connection };
		} catch (error) {
			this.reportCommandSpan(method, commandTrace, {
				startEpochMs: fetchStartEpochMs,
				durationMs: this.options.timing.clock.monotonicNow() - fetchStartMonotonicMs,
				isError: true,
			});
			if (error instanceof SandGatewayCommandError) throw error;
			const classified = classifyGatewayError(error);
			this.reportReachability(
				{
					outcome: classified.outcome,
					method,
					latencyMs: this.options.timing.clock.monotonicNow() - startMonotonicMs,
					baseUrlKind: classifyBaseUrlKind(connection?.baseUrl),
					...(classified.httpStatus !== undefined ? { httpStatus: classified.httpStatus } : {}),
					...(classified.causeSummary !== undefined
						? { causeSummary: classified.causeSummary }
						: {}),
				},
				connection?.baseUrl,
			);
			if (error instanceof SandGatewayUnreachableError) throw error;
			const blocked = findSandBoxBlockedMessage(error);
			throw new SandGatewayUnreachableError(
				classified.outcome,
				blocked == null
					? `gateway ${method} unreachable (${classified.outcome})`
					: `gateway ${method} unreachable (${classified.outcome}): ${blocked}`,
				{
					cause: error,
					...(classified.causeSummary !== undefined
						? { causeSummary: classified.causeSummary }
						: {}),
				},
			);
		}
	}

	private async command<TResult>(
		method: string,
		args?: object,
		init?: { readonly signal?: AbortSignal },
	): Promise<TResult> {
		return (await this.request<TResult>(method, args, init)).result;
	}

	/**
	 * The generic entry BOTH port servers dispatch request frames through
	 * (typed over the renderer-plus-main served union,
	 * shared/rpc/coordinator-main.ts; each session's dispatch scopes itself
	 * to its own table's membership first): every contract method is the
	 * same call shape — POST /api/<name> with the single argument as the
	 * JSON body — so this routes off the method NAME, keyed by the shared
	 * contract tables the servers already checked membership against. Only
	 * methods with a BEHAVIORAL override (the bounded send, the noVNC
	 * rewrite, the bounded boot-blocking roster reads) leave the uniform
	 * path; a new contract entry is served with zero edits here. `signal`
	 * cancels the uniform POST; the send path
	 * deliberately ignores it (aborting a possibly-accepted send buys
	 * nothing — the reply settles as cancelled at the envelope layer and the
	 * nonce ledger dedupes).
	 */
	dispatchCommand<M extends keyof CoordinatorServedMethods & string>(
		method: M,
		args: CoordinatorServedMethods[M]["args"],
		init?: { readonly signal?: AbortSignal },
	): Promise<CoordinatorServedMethods[M]["reply"]> {
		type Reply = Promise<CoordinatorServedMethods[M]["reply"]>;
		if (method === "sendPrompt") {
			return this.sendPrompt(args as SandSendPromptArgs) as Reply;
		}
		if (method === "getForeverBoxStatus" || method === "ensureForeverBox") {
			return this.foreverBoxStatusCommand(method, args as object, init) as Reply;
		}
		if (method === "listAgents" || method === "countAgents") {
			return this.boundedRosterRead(method, init) as Reply;
		}
		if (method === "setDevGatewayOffline") {
			const induced = (args as { readonly induced?: unknown }).induced === true;
			return Promise.resolve(this.setDevInducedOffline(induced)) as Reply;
		}
		if (method === "setGatewayPaused") {
			const paused = (args as { readonly paused?: unknown }).paused === true;
			return Promise.resolve(this.setClientPaused(paused)) as Reply;
		}
		return this.command(method, args as object, init) as Reply;
	}

	/** The uniform POST path for the one legacy command outside the shared contract tables. */
	async dispatchLegacyCommand(method: string, args: object): Promise<void> {
		await this.command<unknown>(method, args);
	}

	// The boot-blocking roster reads (why: ROSTER_READ_TIMEOUT_MS) get the
	// bounded attempt plus ONE idempotent retry on a fresh resolve + socket.
	// Mutations never auto-retry: a timed-out reply may already be applied.
	private async boundedRosterRead<TResult>(
		method: "listAgents" | "countAgents",
		init?: { readonly signal?: AbortSignal },
	): Promise<TResult> {
		try {
			return await this.boundedRosterReadAttempt<TResult>(method, init);
		} catch (error) {
			const isRetryable =
				!this.isClosed &&
				init?.signal?.aborted !== true &&
				!(error instanceof SandGatewayCommandError) &&
				!(error instanceof SandGatewayUnreachableError && PERMANENT_REFUSAL_KINDS.has(error.kind));
			if (!isRetryable) throw error;
			try {
				this.options.onTransportRetry?.();
			} catch {}
			return await this.boundedRosterReadAttempt<TResult>(method, init);
		}
	}

	private async boundedRosterReadAttempt<TResult>(
		method: "listAgents" | "countAgents",
		init?: { readonly signal?: AbortSignal },
	): Promise<TResult> {
		try {
			return await this.options.timing.rosterReadDeadline.run(
				async (signal) => await this.command<TResult>(method, {}, { signal }),
				init?.signal,
			);
		} catch (error) {
			if (error instanceof DeadlineExceededError) {
				throw new SandGatewayUnreachableError(
					"timeout",
					`gateway ${method} unreachable (timeout)`,
					{ cause: error },
				);
			}
			throw error;
		}
	}

	// Base URLs of every gateway whose sendPrompt reply carried
	// `accepted: true` — the NEW host's acceptance-return marker, which also
	// means the host dedupes retries by clientNonce. This is the capability
	// probe gating the idempotent retry: a retry that re-POSTs a possibly-
	// already-received send against an OLD (turn-scoped, dedupe-less) host could
	// double-send, so such a retry only ever targets a base URL that has PROVEN
	// dedupe on a prior response. A set (not a single slot) so bouncing between
	// proven endpoints (e.g. loopback dev + a pod URL) never forgets one.
	// Bounded by construction: connections rotate rarely (box recreates).
	private readonly sendDedupeProvenBaseUrls = new Set<string>();

	// The send command leaves the uniform path (see dispatchCommand) so the
	// latency-critical send POST — the user's gray→ack path — gets:
	//
	//   - a BOUNDED deadline (the gateway-send-post policy): the host resolves
	//     the send at durable acceptance, so a response past the bound is a
	//     wedged connection, not a slow send — fail fast instead of graying
	//     forever;
	//   - ONE idempotent retry on a TRANSPORT failure (connect refused/reset,
	//     the deadline above): the host dedupes by clientNonce, so a retry of an
	//     already-accepted send is a no-op success, never a double-send. A reply
	//     the gateway actually made (SandGatewayCommandError) is never retried;
	//     a send without a nonce, or against a host that has not PROVEN the
	//     dedupe capability (an older turn-scoped host), is never retried;
	//   - nonce-correlated stage reports (`gateway-connect`, `gateway-post`) to
	//     the injected recorder, so the transport share of the ack window is
	//     measured per stage instead of assumed.
	//
	// Kill-switch parity: with SAND_DISABLE_SEND_ACCEPT_RETURN=1 this reverts to
	// the plain unbounded command path (no timeout, no retry, no stage reports).
	//
	// The host's acceptance result flows through to the caller: `accepted:
	// true` is the durable-acceptance marker (an older host resolves void),
	// which the renderer's source adapter forwards to the Client journal. Same
	// value the dedupe probe below already reads off the reply.
	async sendPrompt(args: SandSendPromptArgs): Promise<SandSendPromptResult | void> {
		if (this.sendAcceptReturnDisabled) {
			return await this.command<SandSendPromptResult | void>("sendPrompt", args);
		}
		// What the first attempt actually did, for the retry-safety decision:
		// which endpoint it targeted, and whether the POST was ever dispatched.
		const firstAttempt = { baseUrl: undefined as string | undefined, postStarted: false };
		try {
			return await this.sendPromptAttempt(args, 0, firstAttempt);
		} catch (error) {
			// A retry is safe in exactly two shapes:
			//  - the first attempt FAILED BEFORE ITS POST was dispatched (connection
			//    resolution failed): nothing was sent, so a retry cannot double-send
			//    regardless of host version;
			//  - the POST was dispatched to an endpoint that has PROVEN clientNonce
			//    dedupe on a prior response — the host will treat the re-send as a
			//    no-op. An unproven endpoint (an older turn-scoped host, or a
			//    just-rotated URL with no successful send yet) is failed fast
			//    instead: a double-send is worse than a surfaced failure.
			const postNeverDispatched = !firstAttempt.postStarted;
			const dedupeProven =
				firstAttempt.baseUrl != null && this.sendDedupeProvenBaseUrls.has(firstAttempt.baseUrl);
			const isRetryable =
				!this.isClosed &&
				args.clientNonce != null &&
				args.clientNonce.length > 0 &&
				!(error instanceof SandGatewayCommandError) &&
				(postNeverDispatched || dedupeProven);
			if (!isRetryable) throw error;
			try {
				this.options.onTransportRetry?.();
			} catch {}
			return await this.sendPromptAttempt(
				args,
				1,
				{ baseUrl: undefined, postStarted: false },
				postNeverDispatched ? undefined : firstAttempt.baseUrl,
			);
		}
	}

	private async sendPromptAttempt(
		args: SandSendPromptArgs,
		attempt: number,
		state: { baseUrl: string | undefined; postStarted: boolean },
		requiredBaseUrl?: string,
	): Promise<SandSendPromptResult | void> {
		const clock = this.options.timing.clock;
		const connectStartEpochMs = clock.now();
		const connectStartMonotonicMs = clock.monotonicNow();
		const connection = await this.resolveConnection();
		state.baseUrl = connection.baseUrl;
		if (requiredBaseUrl != null && connection.baseUrl !== requiredBaseUrl) {
			throw new Error("send retry aborted: the gateway endpoint changed mid-send");
		}
		this.recordSendStage({
			stage: "gateway-connect",
			attempt,
			clientNonce: args.clientNonce,
			traceparent: args.traceparent,
			startEpochMs: connectStartEpochMs,
			durationMs: clock.monotonicNow() - connectStartMonotonicMs,
		});
		const postStartEpochMs = clock.now();
		const postStartMonotonicMs = clock.monotonicNow();
		try {
			state.postStarted = true;
			const result = await this.options.timing.sendPostDeadline.run(async (signal) => {
				const response = await fetch(`${connection.baseUrl}${GATEWAY_API_PREFIX}/sendPrompt`, {
					method: "POST",
					headers: this.requestHeaders({ "content-type": "application/json" }, connection),
					body: JSON.stringify(args),
					signal,
				});
				if (!response.ok) {
					const detail = await response.text().catch(() => response.statusText);
					throw new SandGatewayCommandError(
						extractGatewayErrorMessage(detail) ?? `gateway sendPrompt failed: ${detail}`,
					);
				}
				return (await response.json()) as SandSendPromptResult | null;
			});
			// Capability probe: this gateway resolves sends at durable acceptance
			// and dedupes retries by clientNonce (an older host replies null), so a
			// FUTURE send's retry may safely target this base URL.
			if (result?.accepted === true) {
				this.sendDedupeProvenBaseUrls.add(connection.baseUrl);
			}
			this.recordSendStage({
				stage: "gateway-post",
				attempt,
				clientNonce: args.clientNonce,
				traceparent: args.traceparent,
				startEpochMs: postStartEpochMs,
				durationMs: clock.monotonicNow() - postStartMonotonicMs,
			});
			return result ?? undefined;
		} catch (error) {
			this.recordSendStage({
				stage: "gateway-post",
				attempt,
				clientNonce: args.clientNonce,
				traceparent: args.traceparent,
				startEpochMs: postStartEpochMs,
				durationMs: clock.monotonicNow() - postStartMonotonicMs,
				isError: true,
			});
			throw error;
		}
	}

	private async foreverBoxStatusCommand(
		method: ForeverBoxStatusMethod,
		args: object,
		init?: { readonly signal?: AbortSignal },
	): Promise<SandForeverBoxStatus | null> {
		// One connection resolve covers both the request and the loopback ->
		// pod-proxied noVNC rewrite, so a box recreate (which rotates the proxied URL
		// and network token) can't land between them. A null reply is the Host's
		// honest "no status yet" (shared contract) and passes through unrewritten.
		// The port's cancel signal rides through: an ensureForeverBox the
		// renderer abandoned must not keep waking a box behind its back.
		const { result, connection } = await this.request<SandForeverBoxStatus | null>(
			method,
			args,
			init,
		);
		return result == null ? null : proxifyForeverBoxStatus(result, connection.vncProxy);
	}

	private async runEventLoop(): Promise<void> {
		// Floor-resetting failure counter: attempt N of the backoff policy waits
		// initialDelay·factor^(N-1) capped at the ceiling — the exact 1s→10s
		// doubling the old backoffMs variable produced — and every established
		// stream or superseding force request resets it so recovery retries
		// promptly.
		let failedAttempts = 0;
		while (!this.isClosed) {
			const attemptGeneration = this.reconnectGeneration;
			try {
				await this.streamEvents(() => {
					failedAttempts = 0;
				}, attemptGeneration);
			} catch {}
			if (this.isClosed) break;
			if (attemptGeneration !== this.reconnectGeneration) {
				failedAttempts = 0;
				continue;
			}
			const backoffController = new AbortController();
			this.activeEventLoopController = backoffController;
			if (attemptGeneration !== this.reconnectGeneration) {
				this.activeEventLoopController = undefined;
				failedAttempts = 0;
				continue;
			}
			failedAttempts += 1;
			const wait = this.options.timing.reconnectBackoff.schedule(
				failedAttempts,
				backoffController.signal,
			);
			try {
				await wait.elapsed;
			} catch {
			} finally {
				wait.dispose();
			}
			if (this.activeEventLoopController === backoffController) {
				this.activeEventLoopController = undefined;
			}
			if (attemptGeneration !== this.reconnectGeneration) {
				failedAttempts = 0;
				continue;
			}
		}
	}

	private async streamEvents(resetBackoff: () => void, attemptGeneration: number): Promise<void> {
		const controller = new AbortController();
		this.activeEventLoopController = controller;
		const connectStartMonotonicMs = this.options.timing.clock.monotonicNow();
		let connection: SandGatewayConnectionInfo | undefined;
		let didConnect = false;
		try {
			let handshake: {
				readonly connection: SandGatewayConnectionInfo;
				readonly reader: ReadableStreamDefaultReader<Uint8Array>;
			};
			try {
				handshake = await this.options.timing.connectDeadline.run(async (deadlineSignal) => {
					const resolved = await this.resolveConnection(deadlineSignal);
					connection = resolved;
					const response = await fetch(`${resolved.baseUrl}${GATEWAY_EVENTS_PATH}`, {
						headers: this.requestHeaders({ accept: "text/event-stream" }, resolved),
						signal: controller.signal,
					});
					// A fetch implementation may settle despite abort. Never install a stream
					// from an attempt that a force request has already superseded.
					if (controller.signal.aborted || attemptGeneration !== this.reconnectGeneration) {
						void response.body?.cancel().catch(() => {});
						throw new Error("gateway connect superseded");
					}
					if (!response.ok || response.body == null) {
						throw new SandGatewayUnreachableError(
							outcomeForHttpStatus(response.status) ?? "network",
							`gateway events failed: ${response.status}`,
							{ httpStatus: response.status },
						);
					}
					return { connection: resolved, reader: response.body.getReader() };
				}, controller.signal);
			} catch (error) {
				if (error instanceof DeadlineExceededError) controller.abort();
				throw error;
			}
			const { reader } = handshake;
			resetBackoff();
			this.connectionCount += 1;
			didConnect = true;
			this.transportState = "connected";
			// Capture the fixed noVNC proxy up front: the block callback closes over
			// this `let connection`, so a const capture keeps its narrowed (non-null)
			// type inside the closure.
			const { vncProxy } = handshake.connection;
			const blocks = new SseBlockDecoder((block) => this.dispatchEventBlock(block, vncProxy));

			let stalled = false;
			const stallWatchdog = this.options.timing.stallWatchdog.arm(() => {
				stalled = true;
				controller.abort();
			});
			// The bounded classification the transport-down event carries out of
			// the finally below (classifyStreamDown) — never a URL or token.
			let down: StreamDownClassification = { reason: "stream-ended", cause: null };
			try {
				this.reportReachability(
					{
						outcome: "ok",
						method: "events",
						latencyMs: this.options.timing.clock.monotonicNow() - connectStartMonotonicMs,
						baseUrlKind: classifyBaseUrlKind(handshake.connection.baseUrl),
					},
					handshake.connection.baseUrl,
				);
				const forcedReconnect =
					this.pendingForcedReconnect != null &&
					this.pendingForcedReconnect.generation <= attemptGeneration;
				this.emitTransportEvent({
					family: "transport-connected",
					payload: { generation: this.connectionCount },
				});
				if (forcedReconnect) {
					this.pendingForcedReconnect?.resolve();
					this.pendingForcedReconnect = undefined;
				}

				for (;;) {
					const result = await reader.read();
					if (result.done) break;
					stallWatchdog.kick();
					blocks.push(result.value);
				}
			} catch (error) {
				down = classifyStreamDown({
					stalled,
					forced: attemptGeneration !== this.reconnectGeneration,
					devInducedOffline: this.devInducedOffline,
					clientPaused: this.clientPaused,
					error,
				});
				throw error;
			} finally {
				stallWatchdog.dispose();
				controller.abort();
				this.notifyDisconnected(down.reason, down.cause);
			}
		} catch (error) {
			if (!didConnect && !this.isClosed && attemptGeneration === this.reconnectGeneration) {
				const classified = classifyGatewayError(error);
				this.reportReachability(
					{
						outcome: classified.outcome,
						method: "events",
						latencyMs: this.options.timing.clock.monotonicNow() - connectStartMonotonicMs,
						baseUrlKind: classifyBaseUrlKind(connection?.baseUrl),
						...(classified.httpStatus !== undefined ? { httpStatus: classified.httpStatus } : {}),
						...(classified.causeSummary !== undefined
							? { causeSummary: classified.causeSummary }
							: {}),
					},
					connection?.baseUrl,
				);
			}
			throw error;
		} finally {
			if (this.activeEventLoopController === controller) {
				this.activeEventLoopController = undefined;
			}
		}
	}

	private dispatchEventBlock(block: string, vncProxy: SandGatewayVncProxyInfo | undefined): void {
		const dataLines = block
			.split("\n")
			.filter((line) => line.startsWith("data:"))
			.map((line) => line.slice("data:".length).trim());
		if (dataLines.length === 0) return;
		try {
			const event = JSON.parse(dataLines.join("\n")) as {
				readonly channel?: unknown;
				readonly payload?: unknown;
			};
			if (typeof event.channel !== "string" || event.channel.length === 0) return;
			if (event.channel === "forever-box") {
				this.options.onEvent({
					channel: "forever-box",
					payload: proxifyForeverBoxStatus(event.payload as SandForeverBoxStatus, vncProxy),
				});
				return;
			}
			this.options.onEvent({ channel: event.channel, payload: event.payload });
		} catch {}
	}
}
