import type { RpcClientOf } from "@sand/dune/rpc";

import type {
	CoordinatorControlEvents,
	CoordinatorControlRpcContract,
} from "../shared/rpc/coordinator-control.js";
import {
	COORDINATOR_PROTOCOL_VERSION,
	type CoordinatorControlCoordinatorFrame,
	type CoordinatorFrame,
	type CoordinatorReplyOutcome,
	parseCoordinatorFrame,
} from "../shared/rpc/coordinator-port.js";

export interface ControlPortEndpoint {
	post(frame: CoordinatorControlCoordinatorFrame): void;
	close(): void;
}

export type ControlPortSettlement =
	| { readonly outcome: "shutdown-requested" }
	| { readonly outcome: "port-closed" }
	| { readonly outcome: "protocol-breach"; readonly detail: string };

export class ControlPortCallError extends Error {
	readonly code: string;

	constructor(code: string, message: string) {
		super(`${code}: ${message}`);
		this.name = "ControlPortCallError";
		this.code = code;
	}
}

export interface ControlPortClient {
	readonly commands: RpcClientOf<CoordinatorControlRpcContract>;
	postEvent<F extends keyof CoordinatorControlEvents & string>(
		family: F,
		payload: CoordinatorControlEvents[F],
	): void;
	handleMessage(value: unknown): void;
	handlePortClosed(): void;
	shutdown(): void;
	readonly settled: Promise<ControlPortSettlement>;
}

interface PendingCall {
	readonly resolve: (value: unknown) => void;
	readonly reject: (error: Error) => void;
}

export function createControlPortClient(endpoint: ControlPortEndpoint): ControlPortClient {
	let phase: "serving" | "settled" = "serving";
	let readyObserved = false;
	let nextRequestId = 0;
	const pending = new Map<string, PendingCall>();
	const { promise: settled, resolve: resolveSettled } =
		Promise.withResolvers<ControlPortSettlement>();

	const settle = (settlement: ControlPortSettlement): void => {
		if (phase === "settled") return;
		phase = "settled";
		for (const call of pending.values()) {
			call.reject(new Error(`control port settled (${settlement.outcome}) before the reply`));
		}
		pending.clear();
		endpoint.close();
		resolveSettled(settlement);
	};

	const breach = (detail: string): void => {
		if (phase === "settled") return;
		endpoint.post({ kind: "lifecycle", phase: "shutdown", reason: "protocol-error", detail });
		settle({ outcome: "protocol-breach", detail });
	};

	endpoint.post({
		kind: "lifecycle",
		phase: "hello",
		protocolVersion: COORDINATOR_PROTOCOL_VERSION,
	});

	const call = (method: string, args: unknown): Promise<unknown> => {
		if (phase === "settled") {
			return Promise.reject(new Error(`control port settled before ${method} was posted`));
		}
		nextRequestId += 1;
		const requestId = `c-${nextRequestId}`;
		const outcome = new Promise<unknown>((resolve, reject) => {
			pending.set(requestId, { resolve, reject });
		});
		endpoint.post({ kind: "request", requestId, method, args });
		return outcome;
	};

	const commands = new Proxy({} as Record<string, unknown>, {
		get(_target, property) {
			if (typeof property !== "string") return undefined;
			return (args: unknown) => call(property, args);
		},
	}) as RpcClientOf<CoordinatorControlRpcContract>;

	const settleReply = (requestId: string, outcome: CoordinatorReplyOutcome): void => {
		const waiting = pending.get(requestId);
		if (waiting == null) return;
		pending.delete(requestId);
		if (outcome.status === "ok") {
			waiting.resolve(outcome.value);
			return;
		}
		waiting.reject(new ControlPortCallError(outcome.failure.code, outcome.failure.message));
	};

	const handleFrame = (frame: CoordinatorFrame): void => {
		if (frame.kind === "lifecycle" && frame.phase === "shutdown") {
			settle(
				frame.reason === "requested"
					? { outcome: "shutdown-requested" }
					: { outcome: "protocol-breach", detail: frame.detail ?? "peer reported a breach" },
			);
			return;
		}
		if (frame.kind === "lifecycle" && frame.phase === "ready") {
			if (readyObserved) {
				breach("ready repeated on a live control session");
				return;
			}
			if (frame.protocolVersion !== COORDINATOR_PROTOCOL_VERSION) {
				breach(
					`ready.protocolVersion ${frame.protocolVersion} is not the supported ${COORDINATOR_PROTOCOL_VERSION}`,
				);
				return;
			}
			readyObserved = true;
			return;
		}
		if (frame.kind === "reply") {
			settleReply(frame.requestId, frame.outcome);
			return;
		}
		breach(`main posted a client-direction ${frame.kind} frame`);
	};

	return {
		commands,
		postEvent(family, payload) {
			if (phase === "settled") return;
			endpoint.post({ kind: "event", family, payload });
		},
		handleMessage(value) {
			if (phase === "settled") return;
			const intake = parseCoordinatorFrame(value);
			if (!intake.accepted) {
				breach(intake.rejection.detail);
				return;
			}
			handleFrame(intake.frame);
		},
		handlePortClosed() {
			settle({ outcome: "port-closed" });
		},
		shutdown() {
			if (phase === "settled") return;
			endpoint.post({ kind: "lifecycle", phase: "shutdown", reason: "requested", detail: null });
			settle({ outcome: "shutdown-requested" });
		},
		settled,
	};
}
