// The coordinator's MessagePort frame protocol. One envelope serves both of
// the coordinator's ports: the renderer DATA port and the Electron-main
// CONTROL port, each with its own direction split below. This module owns
// the wire ENVELOPE: which frames exist, who may send them on which port,
// and the one boundary validator both endpoints run at frame intake. Domain
// payloads stay the shared contract values declared per port —
// coordinator.ts (data) and coordinator-control.ts (control); the generic
// contract dispatch types them, so this module never re-validates domain
// data.
//
// Wire discipline: frames are structured-clone values that are also
// JSON-safe. Absent facts are `null`, never an optional/undefined field, so
// one frame shape survives MessagePort transfer, Node advanced-serialization
// IPC, and JSON logging identically.

/**
 * The port protocol version. Both endpoints ship in the same app package, so
 * negotiation is strict equality: a `hello` carrying any other version is a
 * protocol breach, never a compatibility mode. Capability skew with older
 * Hosts is a gateway-contract concern and does not bend this number.
 *
 * `hello` precedes every frame EXCEPT `shutdown`, which is legal in any
 * phase: an early-abort launcher (window closed mid-spawn) sends shutdown
 * without ever negotiating, and that is an orderly no-op session — exit 0,
 * never a breach. Nothing was negotiated, so nothing can be confused.
 */
export const COORDINATOR_PROTOCOL_VERSION = 1;

/**
 * Reply failure code for a well-formed request naming a method the
 * coordinator does not serve. The generic dispatch answers with this code
 * instead of treating an unknown method as a protocol breach, so a contract
 * table gap settles the caller's promise predictably.
 */
export const COORDINATOR_UNKNOWN_METHOD = "unknown-method";

/**
 * Reply failure code reserved for a request settled by cancellation. Every
 * accepted request settles with exactly one reply; a `cancel` frame that
 * wins the race settles it with this code. Reserved here so every port
 * consumer shares one spelling.
 */
export const COORDINATOR_CANCELLED = "cancelled";

/** Sent by the client exactly once, before any other frame on the port. */
export interface CoordinatorHelloFrame {
	readonly kind: "lifecycle";
	readonly phase: "hello";
	readonly protocolVersion: number;
}

/** The coordinator's answer to a valid `hello`; requests may follow it. */
export interface CoordinatorReadyFrame {
	readonly kind: "lifecycle";
	readonly phase: "ready";
	readonly protocolVersion: number;
}

/**
 * Why a port session ended. `requested` is a clean, deliberate close;
 * `protocol-error` means the sender observed a breach (malformed frame,
 * wrong-direction frame, lifecycle-order violation) and is abandoning the
 * port. The frame layer has no retryable failure: both ends ship in one app
 * package, so a breach is a bug to surface, not a condition to bridge.
 */
export type CoordinatorShutdownReason = "requested" | "protocol-error";

/**
 * Sent by either endpoint as its final frame; the sender closes the port
 * after posting it. `detail` names the structural fact behind a
 * `protocol-error` (never payload values) and is null for `requested`.
 */
export interface CoordinatorShutdownFrame {
	readonly kind: "lifecycle";
	readonly phase: "shutdown";
	readonly reason: CoordinatorShutdownReason;
	readonly detail: string | null;
}

export type CoordinatorLifecycleFrame =
	| CoordinatorHelloFrame
	| CoordinatorReadyFrame
	| CoordinatorShutdownFrame;

/**
 * One method call. `requestId` is client-minted and unique for the port
 * session; it scopes the reply and any cancellation. `method` stays a plain
 * string at the envelope layer; the generic dispatch derived from the
 * port's contract table narrows it (`CoordinatorRpcContract` on the data
 * port, `CoordinatorControlRpcContract` on the control port), and a name
 * outside the table settles as a `COORDINATOR_UNKNOWN_METHOD` reply
 * failure.
 */
export interface CoordinatorRequestFrame {
	readonly kind: "request";
	readonly requestId: string;
	readonly method: string;
	readonly args: unknown;
}

/**
 * Cancels the request with the same `requestId`. Idempotent by design: a
 * cancel racing a completed reply, or naming an unknown or already-settled
 * id, is a no-op, never a breach. A cancel that wins settles its request
 * with a `COORDINATOR_CANCELLED` reply failure.
 */
export interface CoordinatorCancelFrame {
	readonly kind: "cancel";
	readonly requestId: string;
}

/** A declared, stable failure crossing the port inside a reply. */
export interface CoordinatorReplyFailure {
	readonly code: string;
	readonly message: string;
	/**
	 * The coarse transport classification for a `GATEWAY_UNREACHABLE` failure
	 * (the typed SandGatewayUnreachableError kind: `http_5xx`, `network`,
	 * `timeout`, `refused`, `dns`). Structured because the message cannot be
	 * trusted to carry it — the 5xx path deliberately keeps the gateway's
	 * reply text (it feeds user dialogs verbatim), which has no kind token.
	 * Diagnostic/telemetry only; never rendered and never branched on.
	 */
	readonly transportKind?: string;
}

export type CoordinatorReplyOutcome =
	| { readonly status: "ok"; readonly value: unknown }
	| { readonly status: "failed"; readonly failure: CoordinatorReplyFailure };

/**
 * The single settlement of one request. The client drops a reply whose
 * `requestId` it no longer tracks (a late reply after cancellation or
 * disposal), which is what makes late replies settle predictably.
 */
export interface CoordinatorReplyFrame {
	readonly kind: "reply";
	readonly requestId: string;
	readonly outcome: CoordinatorReplyOutcome;
}

/**
 * One pushed domain event. `family` names an event family from the port's
 * shared contract; `payload` preserves the shared domain envelope,
 * including any ordered-replica stamp. The frame layer adds no ordering
 * metadata: the port is FIFO and ordered replicas carry their own stamps.
 */
export interface CoordinatorEventFrame {
	readonly kind: "event";
	readonly family: string;
	readonly payload: unknown;
}

/**
 * Every validated frame the port may carry: request, reply, event,
 * cancellation, or lifecycle.
 */
export type CoordinatorFrame =
	| CoordinatorLifecycleFrame
	| CoordinatorRequestFrame
	| CoordinatorCancelFrame
	| CoordinatorReplyFrame
	| CoordinatorEventFrame;

/** DATA port: frames the renderer-side client may post; the coordinator rejects the rest. */
export type CoordinatorClientFrame =
	| CoordinatorHelloFrame
	| CoordinatorRequestFrame
	| CoordinatorCancelFrame
	| CoordinatorShutdownFrame;

/** DATA port: frames the coordinator may post; the renderer-side client rejects the rest. */
export type CoordinatorServerFrame =
	| CoordinatorReadyFrame
	| CoordinatorReplyFrame
	| CoordinatorEventFrame
	| CoordinatorShutdownFrame;

/**
 * CONTROL port: frames the coordinator may post; Electron main rejects the
 * rest. The coordinator is this port's session client — it announces itself
 * with `hello` after spawn — and, unlike the data port, the client
 * direction carries the event frames too: the coordinator both calls the
 * control commands and emits the transport lifecycle events
 * (`CoordinatorControlRpcContract` in coordinator-control.ts), while main
 * only answers.
 */
export type CoordinatorControlCoordinatorFrame =
	| CoordinatorHelloFrame
	| CoordinatorRequestFrame
	| CoordinatorCancelFrame
	| CoordinatorEventFrame
	| CoordinatorShutdownFrame;

/** CONTROL port: frames Electron main may post; the coordinator rejects the rest. */
export type CoordinatorControlMainFrame =
	| CoordinatorReadyFrame
	| CoordinatorReplyFrame
	| CoordinatorShutdownFrame;

/**
 * Why an inbound value was refused at intake. `detail` names the structural
 * fact that failed and never embeds payload values, so a rejection is safe
 * to log and to echo across the port.
 */
export interface CoordinatorFrameRejection {
	readonly code: "malformed-frame";
	readonly detail: string;
}

export type CoordinatorFrameIntake =
	| { readonly accepted: true; readonly frame: CoordinatorFrame }
	| { readonly accepted: false; readonly rejection: CoordinatorFrameRejection };

function reject(detail: string): CoordinatorFrameIntake {
	return { accepted: false, rejection: { code: "malformed-frame", detail } };
}

function accept(frame: CoordinatorFrame): CoordinatorFrameIntake {
	return { accepted: true, frame };
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function isNonEmptyString(value: unknown): value is string {
	return typeof value === "string" && value.length > 0;
}

/**
 * The one boundary validator, run once at frame intake by BOTH endpoints.
 * It checks the envelope only: discriminants, identity fields, and field
 * presence. `args`, `value`, and `payload` stay `unknown` here because they
 * are shared contract values the generic dispatch types; re-validating them
 * per frame would put a second validator inside the boundary. Unknown extra
 * fields are ignored; strict-equality protocol versioning owns evolution.
 */
export function parseCoordinatorFrame(value: unknown): CoordinatorFrameIntake {
	if (!isRecord(value)) return reject("frame must be an object");
	switch (value.kind) {
		case "lifecycle":
			return parseLifecycle(value);
		case "request": {
			if (!isNonEmptyString(value.requestId)) {
				return reject("request.requestId must be a non-empty string");
			}
			if (!isNonEmptyString(value.method)) {
				return reject("request.method must be a non-empty string");
			}
			if (!("args" in value)) return reject("request.args is missing");
			return accept({
				kind: "request",
				requestId: value.requestId,
				method: value.method,
				args: value.args,
			});
		}
		case "cancel": {
			if (!isNonEmptyString(value.requestId)) {
				return reject("cancel.requestId must be a non-empty string");
			}
			return accept({ kind: "cancel", requestId: value.requestId });
		}
		case "reply": {
			if (!isNonEmptyString(value.requestId)) {
				return reject("reply.requestId must be a non-empty string");
			}
			const outcome = parseReplyOutcome(value.outcome);
			if (outcome == null) return reject("reply.outcome is not a valid outcome");
			return accept({ kind: "reply", requestId: value.requestId, outcome });
		}
		case "event": {
			if (!isNonEmptyString(value.family)) {
				return reject("event.family must be a non-empty string");
			}
			if (!("payload" in value)) return reject("event.payload is missing");
			return accept({ kind: "event", family: value.family, payload: value.payload });
		}
		default:
			return reject("frame.kind must be lifecycle, request, cancel, reply, or event");
	}
}

function parseLifecycle(value: Record<string, unknown>): CoordinatorFrameIntake {
	switch (value.phase) {
		case "hello":
		case "ready": {
			if (typeof value.protocolVersion !== "number") {
				return reject(`lifecycle.${value.phase}.protocolVersion must be a number`);
			}
			return accept({
				kind: "lifecycle",
				phase: value.phase,
				protocolVersion: value.protocolVersion,
			});
		}
		case "shutdown": {
			if (value.reason !== "requested" && value.reason !== "protocol-error") {
				return reject("lifecycle.shutdown.reason must be requested or protocol-error");
			}
			// The detail's presence is tied to the reason, exactly as the
			// frame doc states: a protocol-error names its structural fact,
			// a requested shutdown carries null (no fact to name). Anything
			// else is wire-invalid.
			if (value.reason === "protocol-error") {
				if (typeof value.detail !== "string" || value.detail.length === 0) {
					return reject(
						"lifecycle.shutdown.detail must name the breach for a protocol-error shutdown",
					);
				}
			} else if (value.detail !== null) {
				return reject("lifecycle.shutdown.detail must be null for a requested shutdown");
			}
			return accept({
				kind: "lifecycle",
				phase: "shutdown",
				reason: value.reason,
				detail: value.detail,
			});
		}
		default:
			return reject("lifecycle.phase must be hello, ready, or shutdown");
	}
}

function parseReplyOutcome(value: unknown): CoordinatorReplyOutcome | null {
	if (!isRecord(value)) return null;
	if (value.status === "ok") {
		if (!("value" in value)) return null;
		return { status: "ok", value: value.value };
	}
	if (value.status === "failed") {
		if (!isRecord(value.failure)) return null;
		const { code, message, transportKind } = value.failure;
		if (!isNonEmptyString(code) || typeof message !== "string") return null;
		return {
			status: "failed",
			failure: {
				code,
				message,
				...(isNonEmptyString(transportKind) ? { transportKind } : {}),
			},
		};
	}
	return null;
}

/**
 * Immutable process configuration handed to the coordinator at spawn. It
 * carries no selected agent and no Client state. The local-exec credential
 * handle rides beside `processConfig`; transferred ports always travel
 * BESIDE this value in the carrying message's transfer list, because ports
 * are not clonable values. `dataDir` is the Sand data root the local-exec
 * daemon contract files live under, and `isPackaged` is stamped into the
 * daemon's
 * env as SAND_PACKAGED — both process facts the coordinator must never
 * derive itself (it has no Electron `app` to ask).
 */
export interface CoordinatorProcessConfig {
	readonly appVersion: string;
	readonly isPackaged: boolean;
	readonly dataDir: string;
}

export interface CoordinatorBootstrap {
	readonly processConfig: CoordinatorProcessConfig;
}

export type CoordinatorBootstrapIntake =
	| { readonly accepted: true; readonly bootstrap: CoordinatorBootstrap }
	| { readonly accepted: false; readonly rejection: CoordinatorFrameRejection };

/** Boundary validator for the spawn-time bootstrap value. */
export function parseCoordinatorBootstrap(value: unknown): CoordinatorBootstrapIntake {
	if (!isRecord(value) || !isRecord(value.processConfig)) {
		return {
			accepted: false,
			rejection: { code: "malformed-frame", detail: "bootstrap.processConfig must be an object" },
		};
	}
	const rejectField = (detail: string): CoordinatorBootstrapIntake => ({
		accepted: false,
		rejection: { code: "malformed-frame", detail },
	});
	const { appVersion, isPackaged, dataDir } = value.processConfig;
	if (!isNonEmptyString(appVersion)) {
		return rejectField("bootstrap.processConfig.appVersion must be a non-empty string");
	}
	if (typeof isPackaged !== "boolean") {
		return rejectField("bootstrap.processConfig.isPackaged must be a boolean");
	}
	if (!isNonEmptyString(dataDir)) {
		return rejectField("bootstrap.processConfig.dataDir must be a non-empty string");
	}
	return {
		accepted: true,
		bootstrap: { processConfig: { appVersion, isPackaged, dataDir } },
	};
}

/**
 * The reserved DATA-port event family carrying the coordinator's own
 * transport-state transitions to the renderer. It is deliberately NOT a
 * domain contract family (source.ts: transport state is a port member, not
 * a Host-pushed event), so it lives with the envelope's other reserved
 * spellings: the coordinator posts it through the same event frames, and
 * the renderer-side source routes it to `subscribeTransportState` listeners
 * instead of the domain fan-out. No replay: the payload reports transitions
 * only, matching the port's "initial assumption is connected" contract.
 */
export const COORDINATOR_TRANSPORT_STATE_FAMILY = "coordinator-transport-state";

export interface CoordinatorTransportStatePayload {
	readonly state: "connected" | "down";
}

/**
 * Payload guard for the reserved transport-state family, run by the
 * renderer-side source at intake. Unlike domain payloads (typed by the
 * shared contract and validated by store codecs), this payload is consumed
 * by the port machinery itself, so its one-field shape is checked here.
 */
export function parseCoordinatorTransportState(
	value: unknown,
): CoordinatorTransportStatePayload | null {
	if (!isRecord(value)) return null;
	return value.state === "connected" || value.state === "down" ? { state: value.state } : null;
}

/**
 * The CONTROL channel's carrier over the coordinator's bootstrap transport.
 * The test harness hands the coordinator ONE Node fork-IPC channel;
 * renderer data-port frames ride it bare, and control-port frames ride
 * inside this envelope so the sessions cannot be confused. Production uses
 * real transferred MessagePorts and the envelope stays a fork-IPC fact; the
 * port client and server behind it are endpoint-injected and do not change.
 */
export const COORDINATOR_CONTROL_CHANNEL = "coordinator-control";

export interface CoordinatorControlEnvelope {
	readonly channel: typeof COORDINATOR_CONTROL_CHANNEL;
	readonly frame: unknown;
}

/** Channel discriminator, run by both ends before any frame validation. */
export function asCoordinatorControlEnvelope(value: unknown): CoordinatorControlEnvelope | null {
	if (!isRecord(value) || value.channel !== COORDINATOR_CONTROL_CHANNEL) return null;
	if (!("frame" in value)) return null;
	return { channel: COORDINATOR_CONTROL_CHANNEL, frame: value.frame };
}

/**
 * The MAIN DATA channel's carrier over the same fork-IPC bootstrap
 * transport, exactly like the control envelope above: Electron main's
 * desktop-edge gateway legs (shared/rpc/coordinator-main.ts) ride their own
 * dedicated MessagePort in production, and inside this envelope on the
 * shared test pipe, so the three logical sessions never mix. Renderer data
 * frames stay bare — that wire predates both envelopes and every fixture
 * speaks it.
 */
export const COORDINATOR_MAIN_DATA_CHANNEL = "coordinator-main-data";

export interface CoordinatorMainDataEnvelope {
	readonly channel: typeof COORDINATOR_MAIN_DATA_CHANNEL;
	readonly frame: unknown;
}

/** Channel discriminator, run by both ends before any frame validation. */
export function asCoordinatorMainDataEnvelope(value: unknown): CoordinatorMainDataEnvelope | null {
	if (!isRecord(value) || value.channel !== COORDINATOR_MAIN_DATA_CHANNEL) return null;
	if (!("frame" in value)) return null;
	return { channel: COORDINATOR_MAIN_DATA_CHANNEL, frame: value.frame };
}
