// Pod label keys stamped on Sand boxes (anyrun pods the backend provisions) by
// the backend SandBoxServer, plus the small pure helpers for deriving their
// values. These live in @anysphere/constants (not backend/server) so
// admin/observability tooling — e.g. anytool's Sand Boxes page — can import the
// exact same keys and derivations without depending on a backend build.
//
// SAND_BOX_LABEL_KIND is the original presence marker every Sand box carries;
// the others were added so a listed pod self-describes its owner, build flavor,
// and source image tag. Boxes created before those labels existed simply won't
// have them (tooling treats that as "unknown").
// Presence marker: `"1"` on every Sand box pod (used as the list filter).
export const SAND_BOX_LABEL_KIND = "sand.box";
// Build flavor the box was created for: "prod" | "dev" | "lab".
export const SAND_BOX_LABEL_FLAVOR = "sand.box.flavor";
// The box owner's auth id. Sand tenants are a one-way hash of the auth id, so
// this label is what lets admin tooling map a listed box back to its user.
export const SAND_BOX_LABEL_OWNER = "sand.box.owner-auth-id";
// The image tag the box was created from (e.g. `sand-box-<gitsha>` or the
// moving `sand-box-latest`), so tooling can flag boxes running a stale image
// without re-reading the pod's full registry reference.
export const SAND_BOX_LABEL_IMAGE_TAG = "sand.box.image-tag";
// Immutable marker for boxes created with sand_special_treatment enabled.
export const SAND_BOX_LABEL_SPECIAL_TREATMENT = "sand.box.special-treatment";
// Pod label consumed by anyrun's anygress_v2 egress
// (egress_anygress_v2::policy::CLOUDFLARE_VNET_POD_LABEL): its value is a
// cluster-local Cloudflare Virtual Network KEY (e.g. "team-1"), bound to a
// concrete vnet UUID by the cluster's `virtual_networks` tfvars map. A labeled
// pod's WARP egress rides that vnet's sidecar (dedicated egress IP via the
// vnet's Gateway egress policy); unlabeled pods use the node-default sidecar.
export const CLOUDFLARE_VNET_POD_LABEL = "cf-vnet";
export function sandBoxFlavorFromNamespace(namespace) {
    if (namespace === "dev") {
        return "dev";
    }
    if (namespace === "lab") {
        return "lab";
    }
    return "prod";
}
// The tag portion of an image registry reference (the part after the last `:`,
// ignoring any digest `@sha256:...`). Returns undefined when there's no tag.
export function imageTagFromRegistryReference(ref) {
    var _a;
    if (ref === undefined || ref.length === 0) {
        return undefined;
    }
    // Strip a digest suffix first so a ref like `repo@sha256:...` isn't mistaken
    // for a tag, then take the segment after the final `:` of `host/path:tag`.
    // `split` always yields a first element; the fallback only satisfies
    // consumers compiled under `noUncheckedIndexedAccess`.
    const withoutDigest = (_a = ref.split("@")[0]) !== null && _a !== void 0 ? _a : ref;
    const lastColon = withoutDigest.lastIndexOf(":");
    const lastSlash = withoutDigest.lastIndexOf("/");
    if (lastColon === -1 || lastColon < lastSlash) {
        return undefined;
    }
    const tag = withoutDigest.slice(lastColon + 1);
    return tag.length > 0 ? tag : undefined;
}
// The prefix every Sand box image tag carries: either a concrete
// `sand-box-<gitsha>` (immutable, per build) or the moving `sand-box-latest`.
export const SAND_BOX_IMAGE_TAG_PREFIX = "sand-box-";
// The moving image tag that always points at the newest published box image (the
// broker resolves it to its immutable `sand-box-<gitsha>` sibling at pod-create).
export const SAND_BOX_IMAGE_TAG_LATEST = `${SAND_BOX_IMAGE_TAG_PREFIX}latest`;
// What a short (or full) git sha looks like: 7-40 hex chars. The single definition
// shared by image-tag parsing, the box-image resolver, and the in-box host-bundle
// version check, so "is this a git sha" is decided one way everywhere.
export const SHORT_GIT_SHA_REGEX = /^[0-9a-f]{7,40}$/;
// The source git sha baked into a concrete `sand-box-<gitsha>` image tag, or null
// when the tag is the moving `sand-box-latest` pointer or otherwise not a sha.
export function gitShaFromSandBoxImageTag(tag) {
    if (tag === null || tag === undefined) {
        return null;
    }
    if (!tag.startsWith(SAND_BOX_IMAGE_TAG_PREFIX)) {
        return null;
    }
    const candidate = tag.slice(SAND_BOX_IMAGE_TAG_PREFIX.length);
    return SHORT_GIT_SHA_REGEX.test(candidate) ? candidate : null;
}
// noVNC websockify ports on a Sand box, served through the anyrun pod proxy
// (token-auth): 6080 is the primary desktop; 6081 is the shared token-routing
// websockify that serves each forked window's desktop by `?token=N`. Centralized
// here so the in-box host (which emits loopback URLs on these ports), the broker
// (which exposes them over the pod proxy), and the desktop (which maps a loopback
// URL back to its proxied route by port) can never drift. MUST match the EXPOSE
// in sand/box/Dockerfile.
//
// The anyrun authed public LB only forwards requests carrying the pod network
// token, so buildSandBoxNoVncUrl rides it on the `network_token` query param and
// embeds it in noVNC's `path` (the websockify upgrade) — a webview can't set
// request headers on its own navigations.
export const SAND_BOX_PRIMARY_NOVNC_PORT = 6080;
export const SAND_BOX_FORK_NOVNC_PORT = 6081;
export const SAND_SPECIAL_TREATMENT_NOVNC_PATH = "sand-special-treatment-v1/vnc.html";
export function buildSandBoxNoVncUrl(proxyBaseUrl, networkToken, token, specialTreatment = false) {
    const wake = "resume_lower_s=900&resume_upper_s=18000";
    const tokenParam = token === undefined ? "" : `token=${token}&`;
    const websockifyPath = `websockify?${tokenParam}network_token=${networkToken}&${wake}`;
    const viewerPath = specialTreatment
        ? SAND_SPECIAL_TREATMENT_NOVNC_PATH
        : "vnc.html";
    return `${proxyBaseUrl}/${viewerPath}?network_token=${networkToken}&${wake}&path=${encodeURIComponent(websockifyPath)}`;
}
export function isSandSpecialTreatmentNoVncUrl(value) {
    try {
        return new URL(value).pathname.endsWith(`/${SAND_SPECIAL_TREATMENT_NOVNC_PATH}`);
    }
    catch (_a) {
        return false;
    }
}
