// Reverse WebAuthn channel: the key is USB HID on the laptop and the box is a
// container, so ceremonies run over there. Dial-out only, like
// local-exec-gateway.ts. Outside `${GATEWAY_API_PREFIX}` so they never collide
// with the typed command switch. See sand/tools/webauthn-proxy/README.md.
export const GATEWAY_WEBAUTHN_REQUESTS_PATH = "/webauthn/requests";
export const GATEWAY_WEBAUTHN_RESPONSES_PATH = "/webauthn/responses";

// Reaches the page as a DOMException, so it must read as an instruction.
export const SAND_NO_WEBAUTHN_MACHINE_MESSAGE =
	"Your computer isn't connected right now, so the security key can't be " +
	"reached. Open Grok Bot on the machine your key is plugged into and try again.";

// Distinct from "nothing connected": a registered machine that went quiet.
export const SAND_WEBAUTHN_MACHINE_UNAVAILABLE_MESSAGE =
	"Your computer looks disconnected, so the security key can't be reached. " +
	"Reconnect it and try again.";

// ~3 missed heartbeats, so one dropped POST doesn't flap a healthy machine.
export const SAND_WEBAUTHN_HEARTBEAT_INTERVAL_MS = 10_000;
export const SAND_WEBAUTHN_LIVENESS_WINDOW_MS = 30_000;

// Far longer than local-exec's watchdog: a human must enter a PIN and touch.
export const SAND_WEBAUTHN_CEREMONY_TIMEOUT_MS = 120_000;

export type SandWebAuthnCeremonyKind = "get" | "create";

// `optionsJson` is opaque (parseRequestOptionsFromJSON form) so no field is
// dropped; `origin` is signed into clientDataJSON and the API hides it, so the
// extension reconstructs it.
export interface SandWebAuthnCeremonyRequest {
	readonly kind: SandWebAuthnCeremonyKind;
	readonly origin: string;
	readonly optionsJson: string;
}

// A failure is a value carrying a DOMException name, not a throw: the page must
// see the error WebAuthn would have produced locally.
export type SandWebAuthnCeremonyResult =
	| { readonly ok: true; readonly credentialJson: string }
	| {
			readonly ok: false;
			readonly error: {
				readonly name: string;
				readonly message: string;
				readonly code?: string;
			};
	  };

// host -> desktop, one JSON object per SSE `data:` frame on the requests stream.
export type SandWebAuthnRequestFrame =
	| {
			readonly kind: "ceremony";
			readonly requestId: string;
			readonly ceremony: SandWebAuthnCeremonyRequest;
	  }
	| { readonly kind: "cancel"; readonly requestId: string }
	| { readonly kind: "welcome"; readonly providerId: string };

export type SandWebAuthnDesktopStage =
	| { readonly stage: "grant"; readonly outcome: "ok" | "declined" | "failed" }
	| { readonly stage: "sign"; readonly outcome: "ok" | "failed" };
export type SandWebAuthnStageLeg = SandWebAuthnDesktopStage["stage"];

// desktop -> host. A `stage` frame never settles the ceremony; an older host ignores it.
export type SandWebAuthnResponseFrame =
	| {
			readonly kind: "hello";
			readonly computerId?: string;
			readonly label?: string;
	  }
	| ({ readonly kind: "stage"; readonly requestId: string } & SandWebAuthnDesktopStage)
	| {
			readonly kind: "result";
			readonly requestId: string;
			readonly credentialJson: string;
	  }
	// `name` is a DOMException name, not a Sand-shaped internal error.
	| {
			readonly kind: "error";
			readonly requestId: string;
			readonly name: string;
			readonly message: string;
			readonly code?: string;
	  }
	| { readonly kind: "ping" };

export type SandWebAuthnOriginClass = "cursor_com" | "subdomain" | "external";

export function sandWebAuthnOriginClass(origin: string): SandWebAuthnOriginClass {
	let hostname: string;
	try {
		hostname = new URL(origin).hostname;
	} catch {
		return "external";
	}
	if (hostname === "cursor.com") {
		return "cursor_com";
	}
	return hostname.endsWith(".cursor.com") ? "subdomain" : "external";
}

export interface SandWebAuthnResponseBatch {
	readonly providerId?: string;
	readonly frames: readonly SandWebAuthnResponseFrame[];
}
