import {
	asCoordinatorControlEnvelope,
	asCoordinatorMainDataEnvelope,
	COORDINATOR_CONTROL_CHANNEL,
	COORDINATOR_MAIN_DATA_CHANNEL,
	type CoordinatorBootstrap,
	parseCoordinatorBootstrap,
} from "../shared/rpc/coordinator-port.js";

export interface CarrierChannel {
	post(value: unknown): void;
	close(): void;
}

export interface CarrierIntake {
	onControlFrame(frame: unknown): void;
	onDataFrame(value: unknown): void;
	onMainDataFrame(value: unknown): void;
	onClosed(): void;
}

export interface CoordinatorCarrier {
	readonly kind: "fork-ipc" | "parent-port";
	readonly bootstrap: CoordinatorBootstrap;
	readonly control: CarrierChannel;
	readonly data: CarrierChannel;
	readonly mainData: CarrierChannel;
	bind(intake: CarrierIntake): void;
	/** Electron utility children require explicit exit; Node fork children drain final IPC writes. */
	exitProcess(exitCode: number): void;
}

export interface CarrierRejection {
	readonly detail: string;
}

export type CarrierIntakeResult =
	| { readonly adopted: true; readonly carrier: CoordinatorCarrier }
	| { readonly adopted: false; readonly rejection: CarrierRejection };

const BOOTSTRAP_FLAG = "--bootstrap=";

interface PortLike {
	postMessage(value: unknown): void;
	close?(): void;
	start?(): void;
	on(
		event: "message",
		listener: (event: { data: unknown; ports?: readonly unknown[] }) => void,
	): unknown;
	on(event: "close", listener: () => void): unknown;
}

function isPortLike(value: unknown): value is PortLike {
	if (typeof value !== "object" || value == null) return false;
	const candidate = value as { postMessage?: unknown; on?: unknown };
	return typeof candidate.postMessage === "function" && typeof candidate.on === "function";
}

interface ParentPortProcess {
	parentPort?: unknown;
}

function adoptForkIpc(argv: readonly string[]): CarrierIntakeResult {
	const argument = argv.find((value) => value.startsWith(BOOTSTRAP_FLAG));
	if (argument == null) {
		return { adopted: false, rejection: { detail: "missing --bootstrap argument" } };
	}
	let parsed: unknown;
	try {
		parsed = JSON.parse(argument.slice(BOOTSTRAP_FLAG.length));
	} catch {
		return { adopted: false, rejection: { detail: "--bootstrap is not valid JSON" } };
	}
	const intake = parseCoordinatorBootstrap(parsed);
	if (!intake.accepted) {
		return { adopted: false, rejection: { detail: intake.rejection.detail } };
	}
	const send = process.send?.bind(process);
	if (send == null) {
		return {
			adopted: false,
			rejection: { detail: "no renderer data channel was transferred" },
		};
	}

	let channelClosed = false;
	const closeChannel = (): void => {
		if (channelClosed) return;
		channelClosed = true;
		if (process.connected) process.disconnect();
	};
	const post = (value: unknown): void => {
		// Node IPC reports teardown races as a throw or async EPIPE; the catch and callback absorb both.
		try {
			send(value, () => {});
		} catch {}
	};

	let bound = false;
	return {
		adopted: true,
		carrier: {
			kind: "fork-ipc",
			bootstrap: intake.bootstrap,
			control: {
				post: (frame) => post({ channel: COORDINATOR_CONTROL_CHANNEL, frame }),
				close: closeChannel,
			},
			data: { post, close: closeChannel },
			mainData: {
				post: (frame) => post({ channel: COORDINATOR_MAIN_DATA_CHANNEL, frame }),
				close: closeChannel,
			},
			exitProcess(exitCode: number): void {
				process.exitCode = exitCode;
			},
			bind(intakeHandlers: CarrierIntake): void {
				if (bound) return;
				bound = true;
				process.on("message", (value: unknown) => {
					const controlEnvelope = asCoordinatorControlEnvelope(value);
					if (controlEnvelope != null) {
						intakeHandlers.onControlFrame(controlEnvelope.frame);
						return;
					}
					const mainDataEnvelope = asCoordinatorMainDataEnvelope(value);
					if (mainDataEnvelope != null) {
						intakeHandlers.onMainDataFrame(mainDataEnvelope.frame);
						return;
					}
					intakeHandlers.onDataFrame(value);
				});
				process.on("disconnect", () => {
					channelClosed = true;
					intakeHandlers.onClosed();
				});
			},
		},
	};
}

export function adoptParentPort(
	parentPort: unknown,
	handoff: { data: unknown; ports: readonly unknown[] },
): CarrierIntakeResult {
	void parentPort;
	const body = handoff.data;
	const intake = parseCoordinatorBootstrap(
		typeof body === "object" && body != null && "bootstrap" in body ? body.bootstrap : null,
	);
	if (!intake.accepted) {
		return { adopted: false, rejection: { detail: intake.rejection.detail } };
	}
	const [controlPort, dataPort, mainDataPort] = handoff.ports;
	if (!isPortLike(controlPort) || !isPortLike(dataPort) || !isPortLike(mainDataPort)) {
		return {
			adopted: false,
			rejection: { detail: "parent handoff did not transfer three message ports" },
		};
	}

	const closed = { control: false, data: false, mainData: false };
	const closePort = (port: PortLike, key: keyof typeof closed): void => {
		if (closed[key]) return;
		closed[key] = true;
		port.close?.();
	};
	const postTo = (port: PortLike, key: keyof typeof closed, value: unknown): void => {
		if (closed[key]) return;
		try {
			port.postMessage(value);
		} catch {}
	};

	let bound = false;
	return {
		adopted: true,
		carrier: {
			kind: "parent-port",
			bootstrap: intake.bootstrap,
			control: {
				post: (frame) => postTo(controlPort, "control", frame),
				close: () => closePort(controlPort, "control"),
			},
			data: {
				post: (value) => postTo(dataPort, "data", value),
				close: () => closePort(dataPort, "data"),
			},
			mainData: {
				post: (value) => postTo(mainDataPort, "mainData", value),
				close: () => closePort(mainDataPort, "mainData"),
			},
			exitProcess(exitCode: number): void {
				process.exitCode = exitCode;
				process.exit(exitCode);
			},
			bind(intakeHandlers: CarrierIntake): void {
				if (bound) return;
				bound = true;
				controlPort.on("message", (event) => intakeHandlers.onControlFrame(event.data));
				controlPort.on("close", () => {
					closed.control = true;
					intakeHandlers.onClosed();
				});
				dataPort.on("message", (event) => intakeHandlers.onDataFrame(event.data));
				dataPort.on("close", () => {
					closed.data = true;
					intakeHandlers.onClosed();
				});
				mainDataPort.on("message", (event) => intakeHandlers.onMainDataFrame(event.data));
				mainDataPort.on("close", () => {
					closed.mainData = true;
					intakeHandlers.onClosed();
				});
				controlPort.start?.();
				dataPort.start?.();
				mainDataPort.start?.();
			},
		},
	};
}

export function adoptCarrier(): Promise<CarrierIntakeResult> {
	const parentPort = (process as ParentPortProcess).parentPort;
	if (parentPort != null && isPortLike(parentPort)) {
		return new Promise((resolve) => {
			parentPort.on("message", (event) => {
				resolve(
					adoptParentPort(parentPort, {
						data: event.data,
						ports: event.ports ?? [],
					}),
				);
			});
			parentPort.start?.();
		});
	}
	return Promise.resolve(adoptForkIpc(process.argv));
}
