/** Basenames shared by the daemon and both supervisors. */
export const LOCAL_EXEC_DAEMON_CONNECTION_FILENAME = "local-exec-daemon-connection.json";
export const LOCAL_EXEC_DAEMON_DISCOVERY_FILENAME = "local-exec-daemon.json";
export const LOCAL_EXEC_DAEMON_CREDENTIAL_FILENAME = "local-exec-daemon-credential.json";
/** Where the detached daemon's stdio appends (SpawnLocalExecDaemonArgs.logPath). */
export const LOCAL_EXEC_DAEMON_LOG_FILENAME = "local-exec-daemon.log";
/**
 * Only the coordinator supervisor writes this (never the daemon): a fresh `at`
 * proves a running desktop owns this data root's daemon, which the daemon
 * forwards to the bridge as the `supervised` routing signal (SAND-1238).
 */
export const LOCAL_EXEC_SUPERVISOR_HEARTBEAT_FILENAME = "local-exec-supervisor.json";

/** Supervisor-heartbeat staleness bound: three 30s ticks, so one missed tick never flaps. */
export const SAND_LOCAL_EXEC_SUPERVISED_WINDOW_MS = 90_000;

export interface LocalExecSupervisorHeartbeat {
	readonly pid: number;
	readonly at: number;
}

/**
 * Discovery record used to attach to a live daemon without duplicating it.
 * An absent `inflightCount` from an older daemon is treated as idle.
 */
export interface LocalExecDaemonDiscovery {
	readonly pid: number;
	readonly startedAt: number;
	readonly inflightCount?: number;
}

export interface LocalExecDaemonCredential {
	readonly credential: string;
	readonly backendUrl: string;
	/** Informational expiry; the daemon uses the credential until the backend rejects it. */
	readonly expiresAtMs?: number;
}
