// The node-agent-coordinator executable composition root. It owns process
// bootstrap (boundary-validating the spawn-time CoordinatorBootstrap and
// adopting the transferred channels) and composes the lanes around the
// three port sessions:
//
//   - the renderer DATA port: the one renderer MessagePort server, its
//     request dispatch routed to the gateway client over the shared contract
//     table, and the gateway's SSE fan-in posted back as contract event
//     families;
//   - the MAIN DATA port: a second instance of the SAME peer-agnostic port
//     server, its dispatch scoped to the main-called table
//     (shared/rpc/coordinator-main.ts; disjoint from the renderer table
//     outside its DEV-ONLY agent-data rows) — Electron main's surviving
//     desktop-edge gateway legs. Deliberately OUTSIDE the renderer
//     session's beginSend wrapper: main's table carries no sendPrompt, and
//     its calls carry no clientNonce, so nothing on this port arms a
//     telemetry trace. No event family fans here; main's feeds ride the
//     control port.
//   - the Electron-main CONTROL port: the generic session client that pulls
//     gateway connection resolution, drives the local-exec process
//     operations, carries the telemetry egress, and emits the transport
//     lifecycle events (shared/rpc/coordinator-control.ts, frozen).
//
// The channels ride the carrier's two physical transports: production
// transfers three dedicated MessagePorts through the utility-process
// handoff, and the fork-IPC test wire shares one pipe (renderer data bare,
// control and main-data enveloped). Every session behind them is
// endpoint-injected and does not change.
// Logging: the coordinator's only log surface is structured stderr lines
// prefixed `node-agent-coordinator:` (the frozen control contract carries
// no log leg), so OAuth warnings ride the same stream as the process
// boundary messages below.
//
// Exit codes are process contract, asserted by the process suite:
//   0  clean settlement (requested shutdown or port close, on either port)
//   1  protocol breach observed on either port
//   2  bootstrap failure (bad --bootstrap payload or no transferred channel)

import { hostname } from "node:os";

import { createPollingPolicy, createRetryPolicy, realClock } from "@sand/dune/scheduling";

import { SAND_WEBAUTHN_HEARTBEAT_INTERVAL_MS } from "../shared/webauthn-gateway.js";
import { createWebAuthnProvider } from "./webauthn/provider.js";
import { createSpawnedWebAuthnSigner, resolveWebAuthnSignerPath } from "./webauthn/signer.js";

// Reconnects forever: giving up would silently stop answering key prompts.
function createWebAuthnReconnectPolicy() {
	return createRetryPolicy({
		name: "sand-webauthn-reconnect",
		maxAttempts: Number.MAX_SAFE_INTEGER,
		initialDelayMs: 1_000,
		maxDelayMs: 30_000,
	});
}

import type { AgentsEvent, AgentUpsertedEvent } from "../shared/events.js";
import { isCoordinatorMainMethod } from "../shared/rpc/coordinator-main.js";
import { COORDINATOR_TRANSPORT_STATE_FAMILY } from "../shared/rpc/coordinator-port.js";
import { HOST_ACCOUNT_SLOT } from "../shared/send-acceptance.js";
import { adoptCarrier } from "./carrier.js";
import { createControlPortClient } from "./control-port-client.js";
import {
	CoordinatorGatewayClient,
	createCoordinatorGatewayClientTiming,
	type CoordinatorGatewaySseEvent,
	type CoordinatorGatewayTransportEvent,
} from "./gateway/gateway-client.js";
import { createGatewayDnsDiagnosticReporter } from "./gateway/gateway-dns-diagnostics.js";
import { coordinatorEventFamilyForSseChannel } from "./gateway/gateway-event-families.js";
import { createGatewayRequestDispatch } from "./gateway/gateway-request-dispatcher.js";
import {
	createCoordinatorHostSupervisorTiming,
	SandHostSupervisor,
} from "./gateway/host-supervisor.js";
import {
	createLocalExecDaemonRefreshPolicy,
	createLocalExecDaemonSupervisor,
} from "./local-exec/supervisor.js";
import { McpOAuthForwarder, type McpOAuthPending } from "./oauth/mcp-oauth-forwarder.js";
import {
	createRendererPortServer,
	type CoordinatorRequestDispatch,
} from "./renderer-port-server.js";
import { createTransportStageRecorder } from "./telemetry/index.js";

async function composeCoordinator(): Promise<void> {
	// Transport adoption: the carrier owns which physical wire started this
	// process (fork-IPC from the test harnesses, parent-port from Electron
	// utilityProcess after the cutover) and hands back endpoint-injected
	// channels. Composition below is carrier-blind. The entry bundles as CJS
	// (NODE_PATH banner), so adoption rides one async composition function
	// instead of top-level await; the exit-code contract is unchanged.
	const carrierIntake = await adoptCarrier();
	if (!carrierIntake.adopted) {
		process.stderr.write(`node-agent-coordinator: ${carrierIntake.rejection.detail}\n`);
		process.exit(2);
	}
	const carrier = carrierIntake.carrier;
	const bootstrap = carrier.bootstrap;

	const controlClient = createControlPortClient({
		post: (frame) => carrier.control.post(frame),
		close: () => carrier.control.close(),
	});

	const recorder = createTransportStageRecorder({
		clock: realClock,
		egress: controlClient.commands,
	});
	const dnsDiagnostics = createGatewayDnsDiagnosticReporter((report) =>
		recorder.recordGatewayDnsDiagnostic(report),
	);
	const reportReachability = (
		report: Parameters<typeof recorder.recordGatewayReachability>[0],
		baseUrl?: string,
	): void => {
		recorder.recordGatewayReachability(report);
		dnsDiagnostics.observe(report, baseUrl);
	};

	// Whether the gateway's SSE stream is currently established, flipped on the
	// transport edges below. The supervisor reads it to skip the pre-command
	// /health probe while the stream itself proves the route is alive.
	let isGatewayStreamLive = false;

	const hostSupervisor = new SandHostSupervisor({
		resolveGatewayConnection: () => controlClient.commands.resolveGatewayConnection({}),
		timing: createCoordinatorHostSupervisorTiming(),
		isTransportLive: () => isGatewayStreamLive,
		onReachability: reportReachability,
	});

	// The legacy in-box OAuth handshake's fan-out point: the forwarder
	// subscribes here, and the SSE handler below delivers each shape-guarded
	// `mcp-oauth-pending` payload (the channel has no contract family, so this
	// is its only consumer).
	const oauthPendingHandlers = new Set<(pending: McpOAuthPending) => void>();

	function asMcpOAuthPending(payload: unknown): McpOAuthPending | null {
		if (typeof payload !== "object" || payload == null) return null;
		const { serverName, redirectUrl, state } = payload as Record<string, unknown>;
		if (typeof serverName !== "string" || serverName.length === 0) return null;
		if (typeof redirectUrl !== "string" || redirectUrl.length === 0) return null;
		if (typeof state !== "string" || state.length === 0) return null;
		return { serverName, redirectUrl, state };
	}

	// Mirrors main's echo relay marker (main.cts recordEchoRelayMarker): a
	// pending send's authoritative echo is its user message or attachment entry
	// carrying the clientNonce; the recorder's armed registry makes repeats and
	// unarmed nonces no-ops. Shape-guarded and best-effort: any non-matching
	// payload is ignored.
	function recordEchoIfUserEcho(payload: unknown): void {
		if (typeof payload !== "object" || payload == null) return;
		const event = payload as {
			type?: unknown;
			entry?: { kind?: unknown; role?: unknown; clientNonce?: unknown };
		};
		if (event.type !== "appended") return;
		const entry = event.entry;
		if (typeof entry?.clientNonce !== "string" || entry.clientNonce.length === 0) return;
		const isUserEcho =
			(entry.kind === "message" && entry.role === "user") || entry.kind === "user-attachment";
		if (!isUserEcho) return;
		recorder.recordSendEcho({ accountSlot: HOST_ACCOUNT_SLOT, clientNonce: entry.clientNonce });
	}

	function handleGatewaySseEvent(event: CoordinatorGatewaySseEvent): void {
		if (event.channel === "mcp-oauth-pending") {
			const pending = asMcpOAuthPending(event.payload);
			if (pending == null) return;
			for (const handler of oauthPendingHandlers) handler(pending);
			return;
		}
		if (event.channel === "transcript") recordEchoIfUserEcho(event.payload);
		// The agents feed for Electron main's OS-notification and Dock-badge
		// consumers (coordinator-control.ts `agents-event`): the same two
		// payloads fan to the control port, byte-identical inside the tagged
		// envelope, alongside their data-port families below. The cast is the
		// composition's one boundary statement — SSE payloads pass through
		// unvalidated exactly like the data-port families, and main's consumer
		// is shape-trusted per family (coordinator-control-server.ts).
		if (event.channel === "agents") {
			controlClient.postEvent("agents-event", {
				kind: "agents",
				event: event.payload as AgentsEvent,
			});
		}
		if (event.channel === "agent-upserted") {
			controlClient.postEvent("agents-event", {
				kind: "agent-upserted",
				event: event.payload as AgentUpsertedEvent,
			});
		}
		const family = coordinatorEventFamilyForSseChannel(event.channel);
		if (family == null) return;
		server.postEvent(family, event.payload);
	}

	// The roster seed for main's notification/badge managers, pushed on every
	// established stream (coordinator-control.ts `agents-roster-seed`): the
	// coordinator performs the roster read itself because a main-called read
	// does not fit the frozen direction split. Best-effort by contract — a
	// failed read logs and waits for the next (re)connect or a full
	// agents-event roster to seed the same consumers.
	async function seedAgentsRosterToMain(): Promise<void> {
		try {
			const agents = await gatewayClient.dispatchCommand("listAgents", {});
			controlClient.postEvent("agents-roster-seed", { agents });
		} catch (error) {
			process.stderr.write(
				`node-agent-coordinator: agents roster seed skipped: ${String(error)}\n`,
			);
		}
	}

	function handleTransportEvent(event: CoordinatorGatewayTransportEvent): void {
		controlClient.postEvent(event.family, event.payload);
		if (event.family === "transport-down") {
			// The stream drop is the first observable sign of a box recreate /
			// host bounce; close the stream-liveness gate and drop the
			// health-probe TTL trust in the same tick, so the reconnect
			// re-probes instead of POSTing blind at a possibly-rotated pod
			// (main's onDisconnected does exactly this).
			isGatewayStreamLive = false;
			hostSupervisor.invalidateHealthCache();
			server.postEvent(COORDINATOR_TRANSPORT_STATE_FAMILY, { state: "down" });
			return;
		}
		isGatewayStreamLive = true;
		void localExecSupervisor.refreshConnection();
		// Every established stream re-seeds main's notification/badge roster
		// over the control port (first connect included: generation restarts
		// at 1 per coordinator process, so a coordinator restart re-seeds the
		// fresh control session too).
		void seedAgentsRosterToMain();
		server.postEvent(COORDINATOR_TRANSPORT_STATE_FAMILY, { state: "connected" });
	}

	const gatewayTiming = createCoordinatorGatewayClientTiming();
	const gatewayClient = new CoordinatorGatewayClient({
		resolveConnection: (signal) => hostSupervisor.ensureConnection(signal),
		onEvent: handleGatewaySseEvent,
		onTransportEvent: handleTransportEvent,
		onTransportRetry: () => hostSupervisor.invalidateHealthCache(),
		recordTransportStage: (report) => recorder.recordTransportStage(report),
		onReachability: reportReachability,
		resolveTraceWindowTraceparent: () => controlClient.commands.getRpcTraceWindowTraceparent({}),
		recordGatewayCommandSpan: (report) => recorder.recordGatewayCommandSpan(report),
		timing: gatewayTiming,
	});

	// OAuth loopback: the forwarder rides the gateway's event subscription and
	// the legacy completeMcpOAuth command leg. That command predates the shared
	// contract (current hosts never emit the handshake), so it rides the
	// legacy-command escape, named here and nowhere else.

	const oauthForwarder = new McpOAuthForwarder({
		pendingEvents: {
			subscribe(handler) {
				oauthPendingHandlers.add(handler);
				return {
					dispose() {
						oauthPendingHandlers.delete(handler);
					},
				};
			},
		},
		completion: {
			completeMcpOAuth: (args) => gatewayClient.dispatchLegacyCommand("completeMcpOAuth", args),
		},
		log: {
			warn(warning) {
				process.stderr.write(`node-agent-coordinator: mcp-oauth ${JSON.stringify(warning)}\n`);
			},
		},
	});

	const localExecSupervisor = createLocalExecDaemonSupervisor({
		control: controlClient.commands,
		dataDir: bootstrap.processConfig.dataDir,
		isPackaged: bootstrap.processConfig.isPackaged,
		refreshPolicy: createLocalExecDaemonRefreshPolicy(),
	});

	let webauthnProvider: { start(): void; stop(): void } | undefined;
	const webauthnSignerPath = resolveWebAuthnSignerPath({
		isPackaged: bootstrap.processConfig.isPackaged,
	});
	if (webauthnSignerPath !== undefined) {
		const reportWebAuthnProgress = (status: string): void => {
			void controlClient.commands.updateWebAuthnConsent({ status });
		};
		webauthnProvider = createWebAuthnProvider({
			resolveConnection: () => controlClient.commands.resolveGatewayConnection({}),
			consent: {
				requestConsent: async (ceremony) => {
					const options = JSON.parse(ceremony.optionsJson) as {
						rpId?: string;
						rp?: { id?: string };
					};
					return await controlClient.commands.requestWebAuthnConsent({
						origin: ceremony.origin,
						rpId: options.rpId ?? options.rp?.id ?? ceremony.origin,
					});
				},
				reportProgress: reportWebAuthnProgress,
				finish: () => {
					void controlClient.commands.finishWebAuthnConsent({});
				},
			},
			signer: createSpawnedWebAuthnSigner({
				binaryPath: webauthnSignerPath,
				onStatus: reportWebAuthnProgress,
				onPinRequest: async (request, promptId) => {
					const { pin } = await controlClient.commands.requestWebAuthnPin({
						promptId,
						invalid: request.invalid,
						...(request.retries === undefined ? {} : { retries: request.retries }),
					});
					return pin ?? undefined;
				},
			}),
			heartbeatPolicy: createPollingPolicy({
				name: "sand-webauthn-heartbeat",
				intervalMs: SAND_WEBAUTHN_HEARTBEAT_INTERVAL_MS,
			}),
			reconnectPolicy: createWebAuthnReconnectPolicy(),
			deliveryPolicy: createRetryPolicy({
				name: "sand-webauthn-delivery",
				maxAttempts: 5,
				initialDelayMs: 250,
				maxDelayMs: 4_000,
			}),
			label: hostname(),
		});
		webauthnProvider.start();
	}

	// The renderer DATA port server: request frames route to the gateway client
	// through the contract-table dispatch, wrapped once so a send opens its
	// telemetry trace — the recorder arms the SSE-echo registry keyed by
	// (accountSlot, clientNonce) before the first attempt, mirroring main's
	// send handler (main.cts) registering the pending echo.

	const gatewayDispatch = createGatewayRequestDispatch(gatewayClient);

	const dispatchRequest: CoordinatorRequestDispatch = (method, args, signal) => {
		if (method === "sendPrompt" && typeof args === "object" && args != null) {
			const { clientNonce, traceparent } = args as {
				clientNonce?: unknown;
				traceparent?: unknown;
			};
			recorder.beginSend({
				accountSlot: HOST_ACCOUNT_SLOT,
				clientNonce: typeof clientNonce === "string" ? clientNonce : null,
				traceparent: typeof traceparent === "string" ? traceparent : null,
			});
		}
		return gatewayDispatch(method, args, signal);
	};

	const server = createRendererPortServer(
		{
			post: (frame) => carrier.data.post(frame),
			close: () => carrier.data.close(),
		},
		{
			dispatchRequest,
			onServing: () => {
				if (isGatewayStreamLive) return;
				server.postEvent(COORDINATOR_TRANSPORT_STATE_FAMILY, { state: "down" });
			},
		},
	);

	// The MAIN DATA port server: the same session machine, dispatch scoped to
	// the main-called table, and no telemetry arm — the plain gateway dispatch,
	// never the renderer session's beginSend wrapper (main sends nothing that
	// carries a clientNonce; sendPrompt is not even in its table).

	const mainDispatch = createGatewayRequestDispatch(gatewayClient, isCoordinatorMainMethod);
	const applyPauseToOwnersHoldingTheirOwnBoxConnection = (isPaused: boolean): void => {
		void localExecSupervisor.setPaused(isPaused);
		if (isPaused) webauthnProvider?.stop();
		else webauthnProvider?.start();
	};

	const dispatchMainRequest: CoordinatorRequestDispatch = (method, args, signal) => {
		if (method === "setGatewayPaused" && typeof args === "object" && args != null) {
			const { paused } = args as { readonly paused?: unknown };
			applyPauseToOwnersHoldingTheirOwnBoxConnection(paused === true);
		}
		return mainDispatch(method, args, signal);
	};

	const mainServer = createRendererPortServer(
		{
			post: (frame) => carrier.mainData.post(frame),
			close: () => carrier.mainData.close(),
		},
		{ dispatchRequest: dispatchMainRequest },
	);

	// Process settlement: idempotent, owned here. Any port settling settles
	// the process; every lane disposes, and the carrier then terminates the
	// process the way its wire requires (fork-IPC drains to the exit;
	// parent-port must exit explicitly — a utility process's loop never
	// drains, and Electron main's relaunch-once-per-exit policy fires only
	// on the child's exit event, so a lingering settled coordinator would
	// wedge the transport silently forever).

	let exitSettled = false;
	function settleProcess(exitCode: number): void {
		if (exitSettled) return;
		exitSettled = true;
		gatewayClient.close();
		localExecSupervisor.dispose();
		oauthForwarder.dispose();
		controlClient.shutdown();
		server.handlePortClosed();
		mainServer.handlePortClosed();
		carrier.control.close();
		carrier.data.close();
		carrier.mainData.close();
		carrier.exitProcess(exitCode);
	}

	void server.settled.then((settlement) => {
		if (settlement.outcome === "protocol-breach") {
			process.stderr.write(`node-agent-coordinator: protocol breach: ${settlement.detail}\n`);
			settleProcess(1);
			return;
		}
		settleProcess(0);
	});

	void mainServer.settled.then((settlement) => {
		if (settlement.outcome === "protocol-breach") {
			process.stderr.write(
				`node-agent-coordinator: main-data protocol breach: ${settlement.detail}\n`,
			);
			settleProcess(1);
			return;
		}
		settleProcess(0);
	});

	void controlClient.settled.then((settlement) => {
		if (settlement.outcome === "protocol-breach") {
			process.stderr.write(
				`node-agent-coordinator: control protocol breach: ${settlement.detail}\n`,
			);
			settleProcess(1);
			return;
		}
		settleProcess(0);
	});

	const settleOnCrash = (
		kind: "uncaughtException" | "unhandledRejection",
		value: unknown,
	): void => {
		const error = value instanceof Error ? value : new Error(String(value));
		process.stderr.write(`node-agent-coordinator: ${kind}: ${error.stack ?? String(error)}\n`);
		void controlClient.commands
			.reportProcessCrash({
				kind,
				errorName: error.name,
				errorMessage: error.message,
				errorStack: error.stack ?? null,
			})
			.catch((reportError: unknown) => {
				process.stderr.write(
					`node-agent-coordinator: crash report undelivered: ${String(reportError)}\n`,
				);
			});
		settleProcess(1);
	};
	process.on("uncaughtException", (value) => settleOnCrash("uncaughtException", value));
	process.on("unhandledRejection", (value) => settleOnCrash("unhandledRejection", value));

	carrier.bind({
		onControlFrame: (frame) => controlClient.handleMessage(frame),
		onDataFrame: (value) => server.handleMessage(value),
		onMainDataFrame: (value) => mainServer.handleMessage(value),
		onClosed: () => {
			controlClient.handlePortClosed();
			server.handlePortClosed();
			mainServer.handlePortClosed();
		},
	});

	void localExecSupervisor.start();
	gatewayClient.start();
}

composeCoordinator().catch((error: unknown) => {
	// Composition never rejects by design (adoption resolves rejections,
	// sessions settle through their own promises); an escape here is a
	// breach-level defect, reported on the process contract's exit 1.
	process.stderr.write(`node-agent-coordinator: composition failure: ${String(error)}\n`);
	process.exit(1);
});
