// Each gateway command is a POST to `${GATEWAY_API_PREFIX}/<method>` whose JSON
// body is the method's single argument (absent for the no-arg commands) and
// whose JSON response is the method's resolved value.
export const GATEWAY_API_PREFIX = "/api";
export const GATEWAY_EVENTS_PATH = "/events";
export const GATEWAY_HEALTH_PATH = "/health";

// When the gateway runs with a per-session token (required whenever it binds
// beyond loopback — see gateway-config.ts), every command and the event stream
// must carry `authorization: Bearer <token>`. The host mints the token at
// startup and advertises it in the discovery record so the desktop attaches it
// automatically. `/health` is deliberately exempt: the supervisor probes
// liveness before it has read the token, and it exposes only pid/busy state.
export const GATEWAY_AUTH_SCHEME = "Bearer";

/**
 * Capability header for versioned avatar fetching. Older clients omit it;
 * older Hosts ignore it and continue inlining avatar data.
 */
export const GATEWAY_SLIM_AVATARS_HEADER = "x-sand-slim-avatars";

/** Staff RPC-capture traceparent. Random ids and flags carry no user content. */
export const GATEWAY_TRACEPARENT_HEADER = "traceparent";

/** HTTP-cacheable avatar resource keyed by agent id and immutable version. */
export const GATEWAY_AVATARS_PATH = "/avatars";

// What the desktop polls to decide host reuse (never orphan an in-flight turn) vs replace.
export interface SandGatewayHealth {
	readonly ok: true;
	readonly pid: number;
	readonly isBusy: boolean;
	// True when the only busy contributors are turns parked on pending Auto-review approvals; the hibernation sweep treats that state as idle. Older bundles omit it.
	readonly busyOnlyAwaitingApproval?: boolean;
	readonly activeAgentId: string | null;
	readonly startedAt: number;
	readonly lastBusyAtMs?: number;
}

export interface SandHostStatus {
	readonly hostVersion: string | null;
	readonly latestHostVersion: string | null;
	readonly hostUpdateAvailable: boolean | null;
	readonly isBusy: boolean;
	readonly capabilities?: readonly string[];
}
