// The classified result of one desktop-to-box reachability attempt — the
// connect + /health + command attempts that back the sidebar's "Can't reach
// your computer" state. Only the report's wire shapes live here; the
// classifiers, the typed unreachable error, and the telemetry mapping stay
// with their owners (reportGatewayReachability in rpc/coordinator-control.ts
// carries the report to Electron main). PRIVACY: every field is an
// enum/timing/bounded-cause string — never a URL, token, prompt, or code
// data.

/**
 * The classified outcome of one reachability attempt. `ok` = it succeeded;
 * the failure kinds split what the desktop used to collapse into a single
 * opaque failure so the real causes are distinguishable from telemetry
 * alone:
 *   refused  — nothing accepted the connection (ECONNREFUSED): the box /
 *              pod proxy isn't up yet, or the port is dead.
 *   timeout  — the attempt's deadline fired with no reply: a route that
 *              never answered — the pod-unreachable / wedged-host
 *              fingerprint.
 *   http_5xx — a 5xx: the pod proxy routed but the gateway/host errored.
 *   dns      — the host name did not resolve (ENOTFOUND / EAI_AGAIN).
 *   no_storage — the backend refused box access for a `NO_STORAGE` account.
 *   access_denied — a 401/403 auth/entitlement gate (SAND-1059).
 *   network  — any other transport failure: a live-but-broken route.
 */
export type SandGatewayReachabilityOutcome =
	| "ok"
	| "refused"
	| "timeout"
	| "http_5xx"
	| "dns"
	| "no_storage"
	| "access_denied"
	| "box_blocked"
	| "network";

export const CLOUD_AGENT_STORAGE_DISABLED = "CLOUD_AGENT_STORAGE_DISABLED";
export const GATEWAY_NO_STORAGE_MESSAGE_MARKER =
	"sand box access blocked by privacy mode (no_storage)";
export const GATEWAY_ACCESS_DENIED_MESSAGE_MARKER =
	"sand box access refused by backend access gate (access_denied)";

export const SAND_BOX_BLOCKED = "SAND_BOX_BLOCKED";
export const SAND_BOX_BLOCK_REASON_KEY = "sandBoxBlockReason";

export const SAND_BOX_BLOCKED_FAILURE_CODE = "sand-box-blocked";
export const SAND_ACCESS_BLOCKED_FAILURE_CODE = "sand-access-blocked";

export interface SandBoxBlockedInfo {
	readonly reason: string;
	readonly title: string;
	readonly detail: string;
}

const GATEWAY_BOX_BLOCKED_PREFIX = "sand box blocked by kill switch: ";

const UNIT_SEPARATOR_NEVER_IN_COPY = "\u001f";

const MAX_BLOCK_FIELD_LENGTH = 400;

function isRenderableField(value: string | undefined): value is string {
	return value !== undefined && value.length > 0 && value.length <= MAX_BLOCK_FIELD_LENGTH;
}

function isBoundedField(value: string | undefined): value is string {
	return value !== undefined && value.length <= MAX_BLOCK_FIELD_LENGTH;
}

export function encodeSandBoxBlockedMessage(info: SandBoxBlockedInfo): string {
	const fields = [info.reason, info.title, info.detail].join(UNIT_SEPARATOR_NEVER_IN_COPY);
	return `${GATEWAY_BOX_BLOCKED_PREFIX}${fields}`;
}

export function hasSandBoxBlockedMarker(message: string): boolean {
	return message.includes(GATEWAY_BOX_BLOCKED_PREFIX);
}

export const SAND_CLIENT_PAUSE_REASON = "SAND_CLIENT_PAUSE";

export const SAND_CLIENT_PAUSE_BLOCKED_MESSAGE = encodeSandBoxBlockedMessage({
	reason: SAND_CLIENT_PAUSE_REASON,
	title: "",
	detail: "",
});

export function findSandBoxBlockedMessage(error: unknown): string | null {
	const seen = new Set<unknown>();
	let current: unknown = error;
	while (current != null && typeof current === "object" && !seen.has(current)) {
		seen.add(current);
		const node = current as { message?: unknown; cause?: unknown };
		if (typeof node.message === "string") {
			const start = node.message.indexOf(GATEWAY_BOX_BLOCKED_PREFIX);
			if (start !== -1) return node.message.slice(start);
		}
		current = node.cause;
	}
	return null;
}

export function decodeSandBoxBlockedMessage(message: string): SandBoxBlockedInfo | null {
	const start = message.indexOf(GATEWAY_BOX_BLOCKED_PREFIX);
	if (start === -1) return null;
	const fields = message
		.slice(start + GATEWAY_BOX_BLOCKED_PREFIX.length)
		.split(UNIT_SEPARATOR_NEVER_IN_COPY);
	if (fields.length !== 3) return null;
	const [reason, title, detail] = fields;
	if (!isBoundedField(reason) || !isRenderableField(title) || !isRenderableField(detail)) {
		return null;
	}
	return { reason, title, detail };
}

/**
 * Where a base URL points, WITHOUT ever logging the URL itself (privacy +
 * low cardinality): a local loopback dev host vs a box reached through the
 * anyrun pod proxy. "unknown" only when the connection never resolved (no
 * URL yet).
 */
export type SandGatewayBaseUrlKind = "loopback" | "pod_proxy" | "unknown";

/**
 * One reachability attempt result. `method` is the gateway command name
 * (e.g. "listAgents" — the roster fetch behind the unreachable state), the
 * SSE "events" connect, or the "health" probe.
 */
export interface SandGatewayReachabilityReport {
	readonly outcome: SandGatewayReachabilityOutcome;
	readonly method: string;
	readonly latencyMs: number;
	readonly baseUrlKind: SandGatewayBaseUrlKind;
	/**
	 * The HTTP status when a response came back (an http_5xx, or a non-ok
	 * health probe). Absent for a transport failure that produced no
	 * response.
	 */
	readonly httpStatus?: number;
	/**
	 * A short, bounded classification of the failure cause — the Error name
	 * and/or the Node system errno (e.g. "AbortError/undefined",
	 * "TypeError/ECONNREFUSED"). Never a URL, token, or code data.
	 * Undefined on `ok`.
	 */
	readonly causeSummary?: string;
}

export type SandGatewayDnsCluster = "dev4" | "us8";

export type SandGatewayDnsProbeResult =
	| "resolved"
	| "not_found"
	| "temporary_failure"
	| "timeout"
	| "error";

export type SandGatewayDnsDiagnosis =
	| "system_path_failure"
	| "independent_path_failure"
	| "endpoint_failure"
	| "cursorvm_failure"
	| "general_dns_failure"
	| "resolved_before_probe"
	| "inconclusive";

export type SandGatewayDnsTrigger = "not_found" | "temporary_failure" | "unknown";

export interface SandGatewayDnsDiagnosticReport {
	readonly cluster: SandGatewayDnsCluster;
	readonly trigger: SandGatewayDnsTrigger;
	readonly diagnosis: SandGatewayDnsDiagnosis;
	readonly systemExact: SandGatewayDnsProbeResult;
	readonly independentExact: SandGatewayDnsProbeResult;
	readonly independentWildcard: SandGatewayDnsProbeResult;
	readonly independentGeneral: SandGatewayDnsProbeResult;
}
