// The Electron-main-to-coordinator MAIN DATA PORT edge declaration. Electron
// main keeps desktop-edge families whose legs rode
// its retired gateway client (attachment reads/staging/uploads/downloads, the
// sand-media remote range reader, Host settings, the MCP
// refresh and box MCP listings, the box-secrets sync push, the
// computer-update dev fallback, and window-focus forwarding). Those legs are
// MAIN-CALLED, and the frozen control contract
// (shared/rpc/coordinator-control.ts) is coordinator-called only, so they
// ride a dedicated third MessagePort channel — the "main data port" — where
// the coordinator runs the SAME session server and generic contract-table
// dispatch the renderer data port uses.
//
// Like coordinator.ts, this contract is a relay declaration: every method is
// gateway-shaped (the Host serves it over the box's gateway) and reuses the
// gateway edge's payload declarations rather than restating them. The two
// tables are deliberately DISJOINT surfaces of one gateway client: the
// renderer surface (coordinator.ts) never gains a main-only leg, and main
// never calls a renderer method over its port — each session's dispatch
// checks membership in its own table, so a cross-port method settles as the
// reserved unknown-method reply failure. ONE commented exception below: the
// DEV-ONLY agent-data rows are members of BOTH tables, because Electron
// main's dev-capability handlers read the same agent data the renderer
// owns; coordinator-main.test.ts pins the overlap to exactly those rows.

import { declareRpcContract, type RpcMethod } from "@sand/dune/rpc";

import type { CoordinatorMethodArgsArity, CoordinatorMethods } from "./coordinator.js";
import type { GatewayRpcContract } from "./gateway.js";

/** Coordinator-local methods — the one deliberate exception to "every method is gateway-shaped": served by the coordinator's own gateway client, never relayed to the Host. `setDevGatewayOffline` is dev-only; `setGatewayPaused` carries main's `sand_client_pause` verdict, which refuses every box connection and drops the live stream. */
export type CoordinatorMainLocalMethods = {
	readonly setDevGatewayOffline: RpcMethod<
		{ readonly induced: boolean },
		{ readonly induced: boolean }
	>;
	readonly setGatewayPaused: RpcMethod<{ readonly paused: boolean }, { readonly paused: boolean }>;
};

/**
 * The main-called desktop-edge methods, exactly the legs `main.cts` keeps
 * (its `CoordinatorGatewayLegs` seam) plus the `getHostSettings` read the
 * transport-connected resync chain's MCP custom-instruction scope
 * reconciliation performs (the retired bridge's
 * `reconcileMcpCustomInstructions` semantics), plus the DEV-ONLY agent-data
 * legs (sandDev capability) and coordinator-local methods above.
 */
export type CoordinatorMainMethods = Pick<
	GatewayRpcContract["methods"],
	| "uploadAttachment"
	| "readAttachmentImage"
	| "readAttachmentText"
	| "readAttachmentChunk"
	| "getHostSettings"
	| "setHostSettings"
	| "setBoxSecrets"
	| "refreshMcp"
	| "listBoxMcpServers"
	| "updateForeverBox"
	| "setWindowFocused"
	| "getHostStatus"
	// DEV-ONLY: the sandDev agent-data legs (see the table's section comment).
	| "listAgents"
	| "createAgent"
	| "deleteAgents"
	| "getConversationOutline"
	| "getSubagents"
> &
	CoordinatorMainLocalMethods;

export interface CoordinatorMainRpcContract {
	readonly methods: CoordinatorMainMethods;
	// The main data port carries no event families: the notification/badge
	// agents feed and the transport lifecycle ride the CONTROL port
	// (coordinator-control.ts), and no main consumer reads a gateway-pushed
	// event today. Declared empty (not omitted) so a future family is a
	// deliberate contract edit here, mirrored by a main-side consumer.
	readonly events: Record<string, never>;
	readonly capabilities: GatewayRpcContract["capabilities"];
	readonly failureCodes: GatewayRpcContract["failureCodes"];
}

export const coordinatorMainRpcContract =
	declareRpcContract<CoordinatorMainRpcContract>("coordinator-main");

/**
 * Every method the coordinator's ONE gateway client serves across its two
 * data-port sessions: the renderer table plus the main table. The client's
 * generic dispatchCommand is typed over this union; each PORT session stays
 * scoped to its own table by the membership guard its dispatch closes over.
 */
export type CoordinatorServedMethods = CoordinatorMethods & CoordinatorMainMethods;

/**
 * The main table as a RUNTIME value, mirroring COORDINATOR_METHOD_TABLE
 * (coordinator.ts): both endpoints route main-port request frames by
 * membership here, and the main-side legs client derives its whole method
 * surface from these rows, so adding a main leg edits this module only — the
 * `Pick` above and one key here. The mapped-type annotation pins the table to
 * `CoordinatorMainMethods` both ways (a missing key, a stray key, and a wrong
 * args arity are each a compile error). No reply-container column: the main
 * legs client trusts replies the way the retired bridge trusted its typed
 * gateway client — main.cts types the surface as a Pick of SandGatewayApi —
 * while the renderer keeps its per-KIND container checks.
 */
export const COORDINATOR_MAIN_METHOD_TABLE: {
	readonly [M in keyof CoordinatorMainMethods]: {
		readonly args: CoordinatorMethodArgsArity<CoordinatorMainMethods[M]["args"]>;
	};
} = {
	uploadAttachment: { args: "object" },
	readAttachmentImage: { args: "object" },
	readAttachmentText: { args: "object" },
	readAttachmentChunk: { args: "object" },
	getHostSettings: { args: "none" },
	setHostSettings: { args: "object" },
	setBoxSecrets: { args: "object" },
	refreshMcp: { args: "object" },
	listBoxMcpServers: { args: "object" },
	updateForeverBox: { args: "object" },
	setWindowFocused: { args: "object" },
	getHostStatus: { args: "none" },
	// DEV-ONLY rows: the agent-data legs behind the control-sand driver's
	// sandDev capability. They exist so the driver's setup capability
	// survives the bridge deletion — main.cts registers the sand:dev-*
	// handlers onto the legs facade only under its unpackaged +
	// SAND_DEV_CAPABILITY dual gate, and preload-sand-dev.cts is their only
	// caller, so packaged builds never expose the callers. Each row is ALSO
	// a renderer-table member (the renderer's own roster/outline/subagent
	// reads are these same gateway methods): the one sanctioned overlap
	// between the two data-port tables, pinned by coordinator-main.test.ts.
	listAgents: { args: "none" },
	createAgent: { args: "object" },
	deleteAgents: { args: "object" },
	getConversationOutline: { args: "object" },
	getSubagents: { args: "object" },
	setDevGatewayOffline: { args: "object" },
	setGatewayPaused: { args: "object" },
};

/** Membership in the main table, as the main-port dispatch's type guard. */
export function isCoordinatorMainMethod(
	name: string,
): name is keyof CoordinatorMainMethods & string {
	return Object.hasOwn(COORDINATOR_MAIN_METHOD_TABLE, name);
}
