import type { CoordinatorRpcContract } from "../../shared/rpc/coordinator.js";

export type CoordinatorEventFamily = keyof CoordinatorRpcContract["events"] & string;

const SSE_CHANNEL_BY_FAMILY: { readonly [F in CoordinatorEventFamily]: string } = {
	transcript: "transcript",
	agents: "agents",
	"agent-upserted": "agent-upserted",
	tray: "tray",
	"agents-workflow": "workflows",
	subagents: "subagents",
	"async-tasks": "async-tasks",
	"agents-automation": "automations",
	"mcp-servers-updated": "mcp-servers",
	"forever-box": "forever-box",
	"teach-recording": "teach-recording",
	"box-disk-pressure": "box-disk-pressure",
	"computer-action": "computer-action",
	outline: "outline",
	sharing: "sharing",
	"host-settings": "host-settings",
};

const FAMILY_BY_SSE_CHANNEL = new Map<string, CoordinatorEventFamily>(
	(Object.entries(SSE_CHANNEL_BY_FAMILY) as [CoordinatorEventFamily, string][]).map(
		([family, channel]) => [channel, family],
	),
);

/** Maps frozen Host SSE channel names to coordinator event-family names. */
export function coordinatorEventFamilyForSseChannel(
	channel: string,
): CoordinatorEventFamily | null {
	return FAMILY_BY_SSE_CHANNEL.get(channel) ?? null;
}
